/* Authored explanations. The Help renderer discovers controls and their order from the live page. */
(() => {
'use strict';
const rules=[];

const notificationHelp='Only the Super Admin can change issue email notifications. Send email notification for new issues, retest issues controls immediate new-issue emails to the configured issue-report recipient and retest or clarification emails to the tester and active testing managers. It includes requests for more information. It is on by default. Turning it back on applies to new events and does not send a catch-up burst for requests made while off. Additional retest reminder emails are independent: turn them on or off and choose 0.25 to 168 hours between emails, then Save Email Notification Settings. Unsaved edits do not change delivery. Changing the immediate-email checkbox does not reset the reminder countdown. A changed reminder schedule starts a fresh countdown. A tester response or issue closure stops retest reminders. In-app and enabled browser reminders retain their four-hour schedule. Email delivery remains subject to the provider daily limit.';

const add=(keys,text,terms=[])=>rules.push({keys:keys.split('|'),text,terms});
add('usageHeading|usageDays|usageUser|usageRefresh','User Usage is available only in Super Admin and starts collapsed. Select User Usage to expand or close the section. Choose a rolling period and a user, or all users, then refresh. Logins are successful sign-ins. Sessions represent browser-tab visits, including returning with an existing sign-in. Active time estimates visible use and pauses after one minute without interaction. Screen visits and active time begin with this release. Feature actions count recorded service operations, not every click. Recent activity shows up to 100 entries. No photo or note content is collected by screen tracking.',['Active time','Session','Screen visit']);
add('data-reader-library|data-ticket-library','Open the saved source photo in Photo Library. A reviewed scanner record is linked to a Photo Note when this action is first used. Reviewed gauge fields remain attached to that photo in supported industry editions and its document output. Existing photo notes are reused.',['Camera reader','Document']);
add('data-reader-reread','Read Again scans this saved source photograph without changing your saved record. Review the new draft and use Save Record to apply it. Analog readings are estimates from the printed dial ticks, including inconsistent scales; verify each scale against the photo.',['Camera reader','Evidence']);
add('areaRetryImagery|mapRetryImagery','Retry Imagery reloads tiles at their best available source resolution. Missing tiles fall back individually without lowering resolution across the map. Close zoom can enlarge imagery without adding detail. The map readout shows zoom, source level and coordinates. Use field measurements when boundaries are unclear.',['Capture Location','Evidence']);
add('data-reader-details|data-reader-edit|data-ticket-details|data-ticket-edit|scannerDetailsClose|data-paving-record-details','Saved specialist cards show a short summary on a light panel with black text in both appearances. View Details opens the complete reviewed information and source photograph. Close Details returns to the list. Edit Record opens saved fields for correction; Save Record or Save Ticket stores your changes. The original photo remains the evidence. Paving library notes expand without changing their export content.',['Camera reader','Evidence']);
add('openSavedScanners|scannerHistory|data-scanner-history','Open saved scanner records only for tools belonging to the current industry edition. New material-label scanning is available in the six industry editions. Gauge/instrument scanning is available in Contractor, Paving, Concrete and the property maintenance editions. Ordinary Pro does not offer new scanner tools. New plan/sketch scanning is available in Contractor, Roofer, Paving, Concrete and the property maintenance editions. Equipment plates are available in Contractor, Paving, Concrete and the property maintenance editions. Business cards are available in Contractor. Ordinary Pro does not show scanner records or scanner shortcuts.',['Camera reader']);
add('readerFormat*|ticketFormat*|data-reader-format|data-reader-download|data-reader-share|data-ticket-download|data-ticket-share','Choose PDF or Word for a report containing the saved record name, source photo, saved date and every nonblank reviewed field. Manually entered details are included. Download Report saves the file; Share Report prepares it, then a fresh Share tap opens the device share sheet. Unsupported browsers offer Download. Sharing cancellation keeps the record. Business cards also offer Contact File, a vCard containing saved contact details for import into a contacts app. Review the exported information before sending.',['Camera reader','Share sheet','Contact file']);
add('exhibit-*|data-exhibit-box|data-exhibit-remove','Proposal Exhibit uses the saved photographs and order of an existing Create document. Set Letter portrait or landscape, exhibit reference, header and footer. Maximum PhotoNotes per page is a limit, not a guaranteed count: long notes continue on additional numbered pages. Choose which title, notes, address, GPS, date, topics and dimensions appear; private comments are excluded. Add Text Box and set its page, left, top and width in inches, measured from the page top left. Text boxes can overlap content, so inspect every page. Update Preview / Save Draft stores settings only on this device for this account and document. Print / Save as PDF opens browser printing: choose Letter and matching orientation, disable browser headers and footers. Close leaves the local draft. This does not change the source photos, create a proposal price or send anything.',['Proposal exhibit']);
add('issueEmailSettings|issueEmailNotificationsEnabled|issueEmailRemindersEnabled|issueEmailReminderHours|saveIssueEmailSettings',notificationHelp,['Email notification','Email reminder','Retest']);
add('speechCheckMethod','Compare a fresh recognizer, a reused recognizer, or a new same-site speech document for each attempt. The document method reloads only a hidden test frame and keeps the results page open. Use Browser default audio with that method. Wait for Start to become available between attempts. If the test frame is unavailable or initialization fails, download the timing; speech did not start and zero results do not establish a recording failure. Reload before changing methods. This diagnostic does not save notes or prove a repair.',['Dictation','Permission']);
add('speechCheckAudio','Keep Browser default for the baseline. Explicit recording session tests supported browser audio-session handling and may interrupt other audio. It does not play sound or start an extra microphone capture. Choose before the first attempt; reload to change. Unsupported browsers show a message. Closing the page restores the previous audio-session type.',['Dictation','Permission']);
add('speechCheck*','Tester-only speech comparison, separate from Capture. Choose new recognizers or reuse of one completed recognizer. Start directly from each tap, speak harmless words, and pause until the attempt ends. Compare three attempts, then download timing metadata for the original issue. Reload before changing methods so speech sessions cannot overlap. No audio or transcripts are retained or uploaded by this page; the browser may use its own speech service. Counts show result events, not transcript accuracy. Stop requests final results. A 45-second limit releases an unresponsive attempt. This is diagnostic evidence, not a saved PhotoNote or a verified repair.',['Dictation','Permission']);
add('micCheck*','Tester-only microphone isolation check: close other microphone and camera sessions. Start requests direct microphone access without speech recognition. Speak harmless test words, Stop, then use the audio player and mark whether you heard your voice. Repeat ten times. Each new attempt releases the previous microphone. Repeat Record Notes after each completed Stop to check that new words are captured; physical-device acceptance is still required. A file with bytes can still be silent; judge actual playback. Download saves metadata only, not audio or spoken words. Include your phone model, operating system and Safari or Home Screen mode. Clear removes the check results and playback. Closing or reloading deletes the local audio. Return opens Photo Notes. No audio is uploaded, saved on the server or sent to a transcription provider. Successful playback does not prove Record Notes works.',['Permission','Dictation']);
add('dictate','Press Record Notes and speak. Capture keeps listening through pauses after receiving words until you press Stop. If no words arrive within 30 seconds of starting, recording stops and offers Restart Recording or Stop. If the browser, microphone or speech connection interrupts recording, a centered dialog offers Restart Recording or Stop. Captured words remain in your note. Wait for Finishing Notes to return to Record Notes before starting again. Saving waits for final words. If the service does not finish within eight seconds, the app releases it and keeps received words. Report repeated failures with Report Issue from the same app. The attached diagnostics include recent speech timing and error codes, never your captured note text or audio. Review names and numbers before saving.',['Dictation','Permission']);
add('data-fu-request','Open the existing Photo Requests form for this occurrence. Creating a request does not send it. Copy or share its private link. The occurrence completes only after all requested views are received; partial submissions retain the open requirement.',['Photo follow-up','Photo Request','Requested view']);
add('data-fu-request-history','Open the existing Photo Request history to see every received view and its own evidence.',['Monitoring history','Photo Request']);
add('pn-help-fab','Select the yellow question mark at the bottom right, aligned with Report Issue, to open searchable Help for the current screen. Close Help to return to your work.');
add('photoToolClose','The location label identifies the originating workflow section and the open photo tool. Close Scheduled Photos or Request Photos to return to the screen you opened it from. Saved schedules and requests remain available. Unsaved form entries are discarded.',['Scheduled photo','Photo Request']);
add('fuOpen|fuRefresh|fuFilter|data-fu-history|data-fu-source','Open Scheduled Photos from Library to plan another photograph of a saved photo or project. View due, overdue, upcoming, completed, or all scheduled photos. Due dates use the schedule time zone. In-app reminders are retained while the app is closed, and push notifications are available when enabled. History references saved photos without duplicating images.',['Scheduled photo','Occurrence','Photo history']);
add('fuType|fuSubject|fuStopRoute|fuTitle|fuReason|fuInstructions','Choose an accessible saved PhotoNote, project, asset, inspection stop, route, or maintenance record. Enter a required reason that explains why another photo is needed. Optional instructions describe how to take it. Route schedules start existing guided visits. Asset and maintenance photos join their existing histories.',['Scheduled photo','Reference photograph']);
add('fuDate|fuTimezone|fuFrequency|fuInterval|fuUnit|fuAdvance|fuAdvanceAmount','Choose the first due date, recurrence, time zone, and advance reminder. Custom reminders accept 1 through 365 days. A due reminder is always retained in the app. Monthly dates stay anchored to the original day and use the last day of shorter months when needed.',['Recurrence','Occurrence','Time zone']);
add('fuAssignee|fuSave|fuEditCancel|data-fu-edit','Save a photographic schedule online. Authorized property/company members may be assigned to property subjects. General Pro schedules notify their owner. Edit Future Schedule changes future dates and instructions while preserving overdue and completed occurrences. Cancel Edit leaves saved scheduling unchanged.',['Photo follow-up','Occurrence']);
add('data-fu-take|fuCaptureCancel','Take Follow-Up Photo opens normal Capture with an earlier reference photograph when available. Take or select a new photo, add its own notes and location, then save. Evidence belongs to the new photo. A device save stays pending until upload and schedule association commit together. Cancel Follow-Up Capture removes scheduling context from the draft. A scheduled route starts or resumes the existing guided visit.',['Reference photograph','Local save','Evidence','Occurrence']);
add('data-fu-skip|data-fu-cancel|data-fu-end','Skip This Occurrence or Cancel This Occurrence retains an optional reason and the history record. Recurring photographs continue. End Recurring Schedule cancels future occurrences and stops generation; overdue occurrences remain available for completion, skip or cancellation.',['Occurrence','Recurrence','Monitoring history']);
add('fuMatchCamera','Match Reference Viewpoint reuses the shared Match Camera preview on supported desktop and Android browsers. Align the earlier photograph with the live view and capture a new photo without the guide. Save normally to satisfy this occurrence. No Before/After pair is forced. Native camera remains the fallback; iPhone and iPad keep the static reference image.',['Reference photograph','Evidence']);
add('fuReferenceLocation','Open the existing Location Intelligence tools for the reference Photo Note. Find its saved subject or capture location using existing maps and navigation actions. Access follows the reference photo permissions; assigned users may need their own accessible property record. No location is copied onto the new photograph.',['Reference photograph','Subject Location']);
add('fuRead|fuPush|fuPushOff','Photo reminders are persistent in-app records. Mark Reminders Read clears unread attention without completing a photograph. Enable Follow-Up Push requires device permission and separately opts this device into photographic reminders. Disable Follow-Up Push stops photographic push on this device. Push failures retry; in-app reminders remain. Delivery requires network and platform notification support.',['Photo follow-up','Web push']);
add('data-fu-photo|data-fu-visit|data-fu-reconcile','Open Photo Note uses shared Edit tools. Open Photo Visit resumes the existing guided visit. Check Visit Completion retries schedule association after all photographic stops have been saved. The server also retries association. Completed visits satisfy one occurrence and retain their existing photographic stop history.',['Monitoring history','Occurrence','Property visit']);
add('hoaCompareEvidence','Compare the existing Original Condition and Completed / Verified maintenance photos side by side or in a temporary overlay. These are selected from the evidence timeline; no additional saved pair is required, and maintenance report stage selection stays unchanged.',['Before/after','Evidence']);
add('alignMatchCamera|matchCameraOpacity|matchCameraFacing|matchCameraCapture|matchCameraNative|matchCameraClose','Match Camera is an optional inline live preview on supported desktop and Android browsers over HTTPS. Allow camera permission, choose Rear or Front Camera, and adjust Reference Opacity over the preview. Capture saves a new image without the ghost guide, then opens post-capture comparison. Cancel stops the camera. Use Native Camera stops preview and keeps the static reference workflow available. iPhone and iPad use native capture and post-capture overlay because live PWA reliability is not verified. No automatic registration or perspective correction is performed.',['Before/after','Evidence']);
add('data-match-photo|toolAlignment','Take Matching Photo opens repeat capture directly from this saved photograph. Match location, camera height, direction, horizon and landmarks. Take After Photo opens the native camera separately, with no live overlay. Where available, the optional Match Camera button opens an inline live preview instead. After returning, compare the images, adjust After-photo opacity, retake if needed, and Save Matched Pair. Each photograph can belong to only one saved pair; unpair first if necessary. This creates no scheduled reminder.',['Before/after','Evidence']);
add('diStart|diRecords|diBack|data-di-record','Property Manager Pro: start Document Damage / Incident from Capture or review your existing photographic records. Select the Property first, enter context, then create one incident before photographing its views. This adds no maintenance item.',['Damage / Incident','Community']);
add('di-property|di-title|di-incident_type|di-other_type','Select the Property and give the incident a clear title. Choose a factual incident type. Other requires your own description. Property cannot change after creation; assets and Areas must belong to that Property.',['Damage / Incident','Community']);
add('di-observed_at|di-reported_at','Observed/Documented Time records when you documented the condition. Reported Incident Time is optional user-entered context if known. Local input is saved with its timezone offset and reports show UTC. A photo does not independently prove when the underlying incident occurred.',['Observed time','Reported incident time']);
add('di-asset_id|di-property_area_id|di-area_name','Optionally link an existing asset or available Area in the selected Property. No asset or Area is required. This feature does not change the asset registry or build a map.',['Asset','Property Area']);
add('di-reported_by|di-observed_by|di-other_party|di-reference_numbers|di-immediate_actions','Enter optional names or descriptions, label any external reference numbers, and record factual immediate actions. These are documentation fields, without contact, claims, police, vendor or task workflows.',['Damage / Incident']);
add('di-status|diSave|diEdit','Save incident context separately from individual photo notes. Open, Documented and Closed organize your records only. Description uses the existing Record Notes dictation control, or typed text. Saving waits for the final dictated words.',['Incident status','Damage / Incident']);
add('diView|diSkipReason|diSkip','Choose Overview, Damage, Close-Up, Surrounding Area, Identification or Additional Photos. Follow the view guidance and use ordinary Capture Save for each photograph. Skip an irrelevant requested view with a written reason. Additional Photos can be repeated without limit. Skipping does not remove photographs already captured.',['Incident view','Damage / Incident']);
add('diReview|diContinue|diRefresh|diExit','Review uploaded incident photographs or continue guided Capture. Save retains photographs in the existing durable device queue until upload succeeds; refresh to see confirmed uploads. Return to Ordinary Capture ends the incident capture context. All incident photographs stay linked to their incident. Exit incident Capture before starting a follow-up; cancel or complete follow-up Capture before continuing incident photos.',['Incident view','Damage / Incident']);
add('diPdf|diWord','Download a Damage & Incident Report with saved context, uploaded photographs grouped by view, photo notes, location, timestamps, markup and skipped-view reasons. Pending device uploads are not included. PDF and Word downloads do not send to anyone. No AI conclusions are added.',['Damage / Incident','Observed time','Reported incident time']);
add('di-*','Enter incident context in the labeled field. Incident Title and valid type are required. Other needs a description. Optional parties, references and immediate-action notes are factual documentation, and observed time is separate from reported incident time. Save Incident Context preserves these fields with the photographic record.',['Damage / Incident']);
add('data-di-photo','Open the existing Photo Notes Edit workflow for this incident photograph: notes, topics, markup, editing, original-file evidence and photo history. Use View & Zoom to inspect the photo. Updates appear in the incident and its next report.',['Photo note','Evidence','Damage / Incident']);
add('ewrDictate|issueRecord','Allow microphone access, press Record, and speak clearly. Press Stop before saving. Review and correct the transcribed words, including names and numbers. You can type instead if speech recognition is unavailable. Speech recognition may require a connection.',['Dictation','Permission']);
add('dimLength|dimWidth|dimDepth|reflen','Enter the dimension identified by this field. Confirm the unit alongside it. Reference length must be a known real-world length visible in the source photo. Use verified site measurements when precision matters.',['Measurement','Reference']);
add('dimLengthUnit|dimWidthUnit|reflenunit','Choose the unit matching the entered measurement. Feet and inches are not interchangeable; review the converted values before saving or exporting.',['Measurement']);
add('dimShape','Choose the shape used to calculate area. A rectangle and circle use different formulas; use Irregular or a reviewed manual area where the subject does not fit either.',['Area']);
add('dimArea','Review the calculated square-foot area or enter a measured override where supported. Confirm dimensions and shape before relying on the result.',['Area','Measurement']);
add('pairSwap|pairConfirm|pairCancel','Create Before & After saves a relationship between exactly two owned photographs. Dates suggest ordering; inspect the images, use Swap Before / After if needed, then Save Before & After. Cancel saves nothing. Unpair preserves both photos.',['Before/after','Selection']);
add('data-view-pair|cmpSaveOpacity|cmpClose','View Before & After opens the shared saved-pair viewer. Side by Side shows both originals; Overlay puts After over Before. Save Comparison Opacity updates only the saved comparison preference. Temporary comparison does not persist changes. Include both pair members in a shared PDF or Word document to export the comparison. Specialist maintenance reports retain their stage-derived comparisons.',['Before/after','Document']);
add('alignPhase|alignPurpose','Concrete repeat capture starts with the original phase and purpose as editable suggestions. Choose the phase and purpose that describe the new photograph; stage is derived from that choice. Topics, owned job, element and exact subject description carry forward. Condition resets to Not Assessed and severity to None. Notes, measurements, mix, findings and AI results are not copied. New GPS is acquired for the new photograph.',['Before/after','Evidence']);
add('dictationStatus','On iPhone, Record Notes prepares a fresh speech document between recordings. Wait for Record Notes to become available, then tap it and speak. If recording ends early, captured words stay in your note. Restart Recording becomes available after the next speech document is ready; tap it to continue, or choose Stop. Stop waits for final words before another recording or Save. Existing notes stay intact. If speech cannot initialize, use Keyboard Microphone or reload; a diagnostic result is not confirmation that Capture is fixed.',['Dictation']);
add('libraryBack','Return to the Photo Library. Opening either member of a saved Before/After pair shows both original photos with their Before and After labels. View Before & After opens the side-by-side or overlay comparison. Each photo keeps its own notes and editing controls.',['Before/after']);
add('alignSaveStatus','If the photo saved but pairing failed, Retry Pairing reuses that saved photo without uploading another. Both photos remain in the library. A changed membership may require unpairing before pairing them again.',['Before/after']);
add('data-visual-analysis|vaRun|vaHistory|vaClose','Concrete Pro: Analyze Photo intentionally sends this saved photograph to the configured AI provider. Review AI Suggested fields alongside existing values. Rerun preserves earlier runs, model, version and timestamps. Close leaves manual documentation available. Failures allow retry. Confidence describes interpretation, not engineering certainty.',['Visual analysis','AI Suggested','Analysis confidence']);
add('va-*|vaObservation|vaFinding*|vaFindingType*|vaAccept|vaReject','Edit suggested fields and visible findings. Check Apply separately for each field you want to replace on the photo. Unchecked fields keep existing values. Accept / Save Review saves a User Reviewed observation for Concrete reports and text search. Reject preserves the AI run without applying it. Original AI results remain in history. Exact location, mix/specifications and measurements are never changed. This is not structural, code or safety certification, cause determination or repair advice.',['User Reviewed','Visual analysis']);

add('bulkMetadataLibrary','Open your own Photo Library from Property Manager or HOA Organize. Select Photo Notes, then Edit Selected for safe metadata changes. Property visits and maintenance records keep their existing specialist workflow.',['Photo note','Topic','Job']);
add('editSelected|bulkMetadataDialog|bulkMetadata-*|data-bulk-metadata-field','Select up to 500 Photo Notes in Organize and choose Edit Selected. Current metadata shows Multiple Values when it differs. Each field starts at Leave unchanged. Choose a replacement or explicitly Remove Topic, Job, or Photo Reason. Replacing Topic removes all existing Topics. Urgency offers Standard or Urgent. Favorite offers Mark Favorite or Remove Favorite. Flagged offers Flag or Remove Flag. Paving offers Proposal Photo context. Concrete offers an optional Element, such as Foundation or Driveway, without changing condition, stage, purpose, measurements or ticket links. Notes, addresses, original evidence, measurements, classifications, specialty maintenance records, and photo relationships are never bulk overwritten.',['Topic','Job','Urgency','Evidence']);
add('bulkMetadataReview|bulkMetadataBack','Review Changes lists only the fields you explicitly chose and the total selected count. Back returns to your choices. Review again if metadata changed since preview. No changes are saved until Apply.',['Topic','Job']);
add('bulkMetadataApply|bulkMetadataCancel','Apply saves the selected changes in one transaction, with Photo History entries for changed fields and their previous values. All selected photos must be editable by your account. A failed operation changes none. The result reports updated, unchanged and not updated counts. There is no automatic Undo. Cancel closes without saving. Existing search filters refresh after success.',['Evidence','Photo note']);
add('leaflet-control-zoom-in|leaflet-control-zoom-out|leaflet-marker-icon','Zoom in or out to inspect the mapped area. Capture Location is fixed evidence. The Subject Location pin can be moved in the Location Intelligence editor; save to record the correction. Map measurements remain separate from subject coordinates.',['Capture Location','Subject Location']);
add('locationView|data-location-id|locationClose|locationLayer|locationMap','View original Capture Location and separate Subject Location on a standard or satellite map. Yellow marks original GPS; the S pin marks the subject and can be moved. Aerial imagery may be outdated and requires a connection. Close returns to your photo.',['Capture Location','Subject Location']);
add('locationFind|locationNavigate','Find This Location requests current device GPS and shows approximate straight-line distance and bearing from north to Subject Location, falling back to Capture Location. GPS accuracy varies indoors. Open in Maps hands the target to your mapping application for a route. Close stops tracking.',['Subject Location','GPS']);
add('locationLatitude|locationLongitude|locationDescription|locationSave|locationClear','Tap the map, move the subject pin, or enter latitude and longitude. Add a landmark description separate from the postal address. Save records these changes in photo history without changing original capture GPS. Clear removes only the draft subject pin until you save. Network access is required; a failed save leaves your draft open. Camera direction appears only when reliable source information exists.',['Capture Location','Subject Location','Location Description','Camera Direction']);
add('data-comments-id|commentsClose|commentsText|commentsPost|commentsCancel|commentsMention|data-comment-reply|data-comment-edit|data-comment-delete','Comments opens Internal Discussion about this saved photograph. Read comments in date order. Post Comment saves text when connected. Reply links to one original comment. Edit changes only your own comment; Delete retains a deletion record and authorized company administrators may remove comments. Choose a team member to insert @Name; authorized HOA and Property team members receive dashboard notifications. Comments are excluded from all external outputs and customer responses. Offline or failed posts keep your draft in this window; copy unfinished text before leaving or reloading. Back to Photo returns to the photograph. Cancel Reply or Edit clears the current draft.',['Internal Discussion','Mention','Comment History']);
add('cfFilterField|cfFilterValue|cfFilterBox','Filter saved Photo Notes by one Choice or Yes / No Custom Field and one saved value. Choose All values to remove the filter. Older choices and inactive field definitions remain available for finding historical photos. This combines with the existing text, topic, job and date search.',['Custom Field','Field scope']);
add('cfCapture|cfManage|cfDialog|cfDefinition|cfName|cfType|cfScope|cfPrompt|cfRequired|cfActive|cfChoices|cfChoicesBox|cfDefinitionSave|cfClose','Additional Details is optional information you define for your own photos, such as an equipment serial number or room name. Skip this for a normal Photo Note when no extra fields are needed. Manage Custom Fields lets you create these fields. Choose Short Text, Number, Date, Yes / No or Choice, a required name, optional prompt and General or current Edition scope. Required is off by default. Save Field requires a connection. Deactivate by clearing Active and saving. Historical and queued values remain intact; type and scope cannot change. Limits: 12 active fields per scope, 60-character names and choices, 300-character prompts, 250-character Short Text and 12 choices.',['Custom Field','Field scope','Field revision']);
add('cfValue-*|cfEdit-*|data-cf-id|cfEditValues|cfValuesDialog|cfValuesSave|cfValuesClose','Additional Details is optional user-entered metadata, separate from photographic evidence and specialty fields. Expand it in Capture, enter applicable values and use Save to Photo Notes. Required fields must be completed. Pending uploads preserve entered values on this device. Photo Details & History displays saved values. Edit Additional Details and Save Additional Details records changes online without changing original photo, receipt time, fingerprint or GPS. Inactive fields retain historical values. Search includes saved values. Documents include completed values, without printing them onto the photograph.',['Custom Field','Field revision','Local save','Evidence']);

add('data-photo-marker','Tap the star to mark or remove Favorite for long-term access. Tap the distinct flag to mark or remove Flagged for personal attention. The pressed state shows the saved designation. A connection is required. These internal markers do not change urgency, topics, maintenance status, priority, assignee or target date, create reminders, or appear on exported photos or customer documents. Toggling is not added to evidence history.',['Favorite','Flagged']);
add('prOpen|prRefresh|data-pr-detail','Request specific photographic information from an outside person without an account. Open Photo Requests to create a private link or review status, received views, submitter names, notes, and history. Refresh to check for new submissions. Received photographs are normal Photo Notes.',['Photo Request','Requested view']);
add('prTitle|prRecipient|prInstructions','Give the request a clear title and explain the photographs needed, including subject and viewpoint. Recipient Name is optional context, not identity verification. The recipient sees your account name and these instructions.',['Photo Request','Private link']);
add('prViews','Enter 1 to 8 distinct requested-view names, one per line. Use your own names such as Overview, Equipment Plate, or Damaged Panel. Each view needs one photograph. All views are required unless you allow partial submissions.',['Requested view']);
add('prRelated|prJob|prItem','Optionally associate the request with your Photo Note, job, or an accessible maintenance record. No existing record is required. Returned photos inherit the selected job and available topics, and attach to the selected maintenance record as inspection evidence. Request completion does not close maintenance work.',['Photo Request','Photo note','Job','Maintenance record']);
add('prDays|prPartial','Links expire after 14 days by default; choose 1 to 30 days. Allow partial submissions lets the recipient send available views and return for missing ones. The request completes and closes only when every requested view is received. Individual optional views are not supported.',['Private link','Requested view','Request status']);
add('prCreate','Save the Photo Request and create its private link. This requires a connection and does not send email or SMS. Copy or share the link yourself, then check the request history for received photographs.',['Photo Request','Private link']);
add('data-pr-copy|data-pr-share','Copy the private request link or open your device share sheet. Send it using your preferred app. Copying or opening a share sheet does not prove delivery. Anyone with the link can submit only to this request until it closes or expires; share it carefully.',['Private link','Share sheet']);
add('data-pr-cancel','Cancel an open or partially submitted Photo Request and close its private link. Already received photographs remain in your Photo Notes library and submission history. Completed and expired requests are already closed.',['Request status']);
add('data-pr-photo','Open the received photograph in Edit with the Photo Note selected. Use the shared Photo Notes tools to organize, annotate, compare, or include it in documents and reports where supported. The request retains its view and submission history.',['Photo note','Evidence']);
add('prSubmitter|prViewNote*','Optionally enter your name and a note for each requested photograph. These are saved with the request, submission time, original filename, and file fingerprint for the requesting user. A typed name is not verified identity.',['Requested view','Fingerprint']);
add('data-pr-camera|data-pr-choose|prCamera*|prChoose*','Take a photograph or choose an existing device image for this requested view. Review the preview. Take / Retake or Choose / Replace changes the selection before submission. Each photo must be supported JPEG, PNG, WebP, or HEIC, up to 25 MB. HEIC support depends on the server decoder. Selected is not yet Received.',['Requested view','Upload']);
add('prPublicSubmit','Upload the selected photographs and optional notes to this private request. Supply all missing views unless partial submissions are allowed. Wait for Photos received before assuming upload succeeded. Once all views are received the link closes. No Photo Notes account is needed.',['Photo Request','Requested view','Upload']);
add('profileButton','Open your account menu to switch versions, access your testing/issue records, inspect pending uploads, install the app, or sign out. Available options depend on your account permissions.',['Account access']);

add('markerPhotoLibrary','Open the shared saved Photo Notes library to find, select, favorite and flag your photographs. Property visit controls remain available from Organize.',['Favorite','Flagged']);
add('markerFavorites|markerFlagged','Show Favorites or Flagged Photo Notes in Organize. Selecting both uses AND and shows only photos with both markers. An empty combined result can be correct even when each separate filter finds photos. Clear either filter to see photos with just one mark. Combine with topic, job, text, date and missing-address filters.',['Favorite','Flagged']);
add('batchMarker|applyMarkers','Select saved photographs, choose Mark as Favorite, Remove Favorite, Flag or Remove Flag, then Apply Markers. This saves only that marker for every selected photo, including selections retained across filters. No selection means no change. Connection required; an unavailable photo prevents the whole batch.',['Favorite','Flagged']);

add('epLibrary|epChoose|epExport|epSave|epAdjust|epEdit|epDuplicate|epDelete|epName|epDescription|epFormat|epQuality|epLayout|epFont|epAccent|data-ep-layout|data-ep-branding|epLogo|epDefault|epCommit|epCancel','Export Presets save your packaging defaults, separate from document photo membership and Send Shortcut destinations. Choose a preset or No preset. Save as Preset copies current settings. Adjust Output Settings applies temporary changes without saving or changing the preset. Edit / Rename changes the selected preset; Duplicate saves a separate copy; Delete keeps your documents and photos. Name is required and Description optional. Default is selected when entering this workspace. Adjust layout, branding, format and image quality before saving or output. Standard is 2048 pixels, Print 3000 and Web 1400, without enlarging smaller originals. Logo uses your current account logo and a removed logo is omitted. Existing photo metadata and markings are retained. Markdown + Photos ignores page layout and branding. Imported Word templates retain their own styling. Unsupported settings fall back safely. Download Using Preset generates the selected photos or current document using the chosen format and temporary settings. Saving a preset does not generate or deliver output.',['Export Preset','Image Quality','Document','Share sheet']);
add('relatedOpen|data-related-id|relatedClose|data-related-open','Related Photos preserves a user-created relationship between independently saved Photo Notes. Open a related photo to view its photograph, title, date and notes, then move among its relationships. Close returns to your workspace. These links are separate from Before/After, Photo Sets, jobs, assets and maintenance evidence.',['Related Photos']);
add('relatedPicker|relatedSearch|relatedMore|data-related-choice|relatedType|relatedNote|relatedLink','Open Link Existing Photos, search or load More Photos, and select one or more existing photographs. Optionally choose a relationship type and explain the connection. Link Selected Photos saves one bidirectional relationship per pair without duplicating either photo. Classification is optional. Cause / Source and Result / Effect are user descriptions, not verified conclusions.',['Related Photos','Relationship type']);
add('data-related-type|data-related-note|data-related-save|data-related-remove','Edit the optional type or note and Save Relationship. Remove Relationship unlinks this pair without deleting either Photo Note. Link, change and unlink events appear in both photo histories. Links are available within your own saved library.',['Related Photos','Relationship type']);
add('relatedSelect','Select the current photo and its directly related photographs for the normal Create document workflow. Review the selection and save the document yourself. Relationships never automatically add photos to a report or document.',['Related Photos','Document']);
add('takephoto|photoCam','Take a photo and check the preview. Capture automatically keeps the unfinished photo and note in this browser for your account and version, and restores them when you reopen PhotoNotes. This device draft is separate from library Save or delivery. Keep browser data until you finish. If automatic recovery fails, follow the warning and save before leaving.',['Capture','Draft','Local save']);
add('readerTake|readerCam|ticketTake|ticketCam|ewrTake|ewrCam','Open the camera and photograph the subject clearly. Keep the important evidence in frame, check the preview, and retake if blurred or incomplete. Camera permission is required. Taking a photo does not by itself save or send it.',['Capture','Permission']);
add('choosephoto|photoLib','Choose a device image for Capture. The unfinished photo and note are automatically retained in this browser and restored for the same account and version. Cancel Photo removes the device draft. It has not been uploaded or sent.',['Capture','Draft','Local save']);
add('readerChoose|readerLib|ticketChoose|ticketLib|alignChoose|alignLib|ewrChoose|ewrLib','Choose an image from this device. Review the imported image before continuing. Imported photos may not contain usable GPS information, so check the displayed location. This selects a photo; use the relevant Save or Send action to complete the task.',['GPS','Capture']);
add('retakePhoto|alignRetake','Replace the current draft photo with another camera shot. Check the replacement preview and location. The unfinished Capture photo and note are automatically kept in this browser for your account and version, and restored when PhotoNotes reopens. This device draft is not an uploaded library record. Use Save where available to create that record. Keep browser data until saved. Retaking does not delete photographs already saved in your library.',['Draft']);
add('cancelPhoto','Discard the current unsaved photo draft and its preview. This does not remove photos previously saved in PhotoNotes.',['Draft']);
add('ewrDictate|issueRecord','Allow microphone access, press Record, and speak clearly. Press Stop before saving. Review and correct the transcribed words, including names and numbers. You can type instead if speech recognition is unavailable. Speech recognition may require a connection.',['Dictation','Permission']);
add('note|editarea|ewrDesc','Explain what the photo shows, why it matters, and any work or follow-up needed. Review dictated text before saving. Editing a note changes supporting text, not the photograph.',['Photo note']);
add('retryConnection','Retry the Photo Notes sign-in service without deleting browser data or pending captures. Other websites working does not prove this service is reachable. Transient session requests retry once. Local recovery problems do not sign you out of your cloud account.',['Installation']);
add('retryLocation','Retry this device’s location permission and GPS lookup, then review the coordinates and address. Device location and address lookups have bounded waits. Safari website permissions are separate from the installed app; if location is blocked, allow it for this website before retrying. Location can be unavailable indoors or when permissions are blocked. Confirm an approximate address before relying on it. Retrying cannot correct missing or inaccurate map-provider names. A distant point-place name is omitted in favor of the broader city or region; GPS coordinates remain unchanged.',['GPS','Geocoding']);
add('correctAddress|editaddress','Enter the correct address or geographic area for this photo. Check street, city, and site details. Correcting address text does not change the photograph or recreate missing GPS coordinates.',['GPS','Geocoding']);
add('gps|addr|locwrap','The coordinates describe the location obtained for this capture. The address is a readable description of those coordinates. Accuracy varies; review both and correct the address when needed. A missing address does not necessarily mean GPS is missing.',['GPS','Geocoding']);
add('qualityStatus|previewBox|readerPreviewBox|ticketPreviewBox|preview','Inspect the photo for legibility, blur, framing, and important details. Follow any quality warning, retake if possible, or consciously keep the available evidence. A preview is not confirmation that the photo has been uploaded.',['Capture','Upload']);
add('save','Save the current photo and note in PhotoNotes. A local save or waiting message means it is stored on this device until upload succeeds. Keep the app connected, and use Pending Photos to check unfinished uploads. A save does not send the photo to another person.',['Local save','Upload']);
add('pendingLibraryCapture','Return from device Library to Capture. Pending PhotoNotes stay saved on this device, and the current automatic retry setting stays in effect. Returning does not delete a PhotoNote or confirm upload.',['Capture','Library','Upload']);
add('pendingRetryToggle','Automatic retry runs every 10 seconds after a connection failure. Stop Retrying pauses uploads for this account and version on this device. Continue Retrying resumes them. An upload already in progress may finish. Account or validation errors need attention before retrying.',['Upload','Local save']);
add('pendingSaveLibrary','Show the saved PhotoNotes in Library on this device, labeled upload pending. Their photos and notes are already stored locally. This does not confirm upload or make them available on another device. Automatic retry continues unless stopped.',['Local save','Upload']);
add('pendingClose','Close the pending PhotoNotes panel. Automatic retry continues unless you selected Stop Retrying. The PhotoNotes remain saved on this device while upload is pending.',['Local save','Upload']);
add('dictationRestart','Restart recording after an unexpected interruption. Previously captured words remain in your note, and new words are added. If microphone access was denied, allow it before restarting. Silence does not stop recording in the app; browser or connection interruptions show this dialog.',['Capture']);
add('dictationStop','Leave recording stopped after an interruption. Keep the words already captured. You can edit the note, record more later, or save the PhotoNote. This button does not delete the photo or note.',['Capture']);
add('captureResultOK','Dismiss the centered Photo Note result with OK. Read the sharing result and save location separately. Device sharing does not identify the destination app or confirm email delivery. Library means upload succeeded; the device pending upload queue means the photo is saved locally and waiting to upload. Canceling or failed sharing retains Capture.',['Share sheet','Local save','Capture']);
add('send','Include the photo, note, both GPS coordinates and address when available, topic, urgency, and completed Capture details in the prepared message. Remove unwanted text in your email app before sending. Basic and Issue Reporter share directly without saving a PhotoNotes account record. Other editions save the current photo and notes before preparing the device sharing choices and show a centered result that requires OK. After successful device sharing, Capture clears for the next photo. Canceling or failed sharing keeps your draft. Opening an email draft or downloading an attachment does not confirm sending and keeps Capture filled. The saved Photo Note remains available in Photo Notes or the upload queue.',['Share sheet','Capture','Local save']);
add('roadIssueType','Choose the type of road problem visible in your photograph. Match the category to the evidence rather than a guess about its cause. Review the camera preview and location before sending. This is different from reporting a fault in the PhotoNotes application.',['Road issue']);
add('roadIssueSend','Submit the road issue category, photograph, and available location. A connection and photo are required. Read the result: a saved report with email pending is different from confirmed email delivery. If it fails, keep the draft and retry after reconnecting.',['Road issue','Upload']);
add('captureTopicHeading|areas|newarea|organizenewtopic','Use your own topics to group related photos. Add a concise reusable topic name, then select it for the current photo. Topics belong only to your account and are not shared with other users. New accounts start with no topics. Removing a topic from your list preserves tags on saved photos. No Topic leaves the photo untagged; adding a topic is optional unless the current workflow says otherwise.',['Topic']);
add('addarea|createtopic','Create the topic using the name in the adjacent field. The new name becomes available in your topic list. Reuse an existing topic when it already describes the subject, to avoid duplicate spellings.',['Topic']);
add('areax','Remove this topic from your selectable list after reviewing the confirmation. Photos already tagged keep their existing labels. This does not delete those photos.',['Topic']);
add('captureUrgencyHeading|captureUrgency','Urgency is optional and defaults to Standard. Expand this row only if you want to change it. Choose Standard for normal handling or Urgent when the captured item needs prompt attention. This saves urgency with the capture. It does not automatically contact emergency services or guarantee that someone has been notified.',['Urgency']);
add('captureUrgencyHeading|captureUrgency','Choose Standard or Urgent for the current photograph. Urgency creates no notification or emergency call. Review before saving.',['Urgency']);
add('openCameraTools|toolsBack|readerBack|ticketBack|alignBack|pavingToolsGuide','Open Camera Tools or return to their menu. New scanner availability depends on the edition and account settings. Business-card scanning is available in every industry-specific Pro edition when Camera Readers is enabled for the account. Plan/sketch and equipment-plate scanners are also industry tools; ordinary Pro has no scanner tools or Saved Scanner Records shortcuts. Paving keeps its Photo Reason entry points. Choose the tool suited to the source photo. Reading, measuring, and saving are separate steps; review extracted values before recording them.',['Camera reader']);
add('pavingPhotoReason','Choose why this paving photograph is being taken. The selection determines which supporting tools or details appear. Read the on-page description and choose the reason supported by the photo.',['Photo purpose']);
add('concretePhase','Choose the project phase that the photo documents, from proposal planning through work, completion, or later follow-up. The photo-purpose choices update to suit the phase. Leave it blank if the phase is not yet known.',['Project phase']);
add('concretePurpose|concretePurposeButton','Choose the specific purpose of the photo within the selected project phase. Read the description beneath the selector. Use this to distinguish a customer wish, existing condition, work stage, completed result, or reported problem.',['Photo purpose']);
add('concreteElement','Choose the photographed project type, such as patio, driveway, slab, or foundation. Use Other when none fits. This describes the physical work, not a defect classification.',['Project']);
add('concreteJob|jobFilter|batchJob|ewrJob','Choose the project or job to associate with the work. A job gathers related evidence for the same site or customer. All Jobs shows records across jobs; Unassigned shows photos with no job, and combines with Topic and Search; No project selected leaves the capture unassigned. Verify the site before applying changes.',['Job','Project']);
add('concreteLocation','Describe exactly where on the property this subject appears, such as the rear patio or north side of the driveway. This supplements the street address and GPS rather than replacing them.',['GPS']);
add('concreteCondition|hapCondition|haCondition','Record the observed physical condition. Not assessed means no judgment has been made. Monitor means follow-up may be needed; repair needed or unsafe should be supported by a clear photo and explanation. Review the choices currently offered for this record.',['Condition']);
add('concreteSeverity|ovsev','Choose the seriousness of the visible issue. Use Not rated or None if it has not been assessed. Severity describes the evidence; it is separate from urgency and maintenance scheduling. Review AI suggestions before saving.',['Severity','Urgency']);
add('concreteMix','Record only a confirmed mix or specification taken from a ticket, approved plan, or other reliable source. Do not infer strength or mix composition from a photograph of finished concrete.',['Specification']);
add('hoaCommunity|haCommunity|hirCommunity|hcName|hrCommunity|hoaFilterCommunity|haFilter','Select or name the community/property to which the photos and records belong. Community filters narrow the results. Check the property before creating a record or starting an inspection route.',['Community']);
add('hoaTitle|hiTitle','Give the maintenance issue a concise title that identifies the subject and location. A clear title makes later searches, assignment, and board reports easier to understand.',['Maintenance record']);
add('hoaType|hoaFilterType','Choose or filter the record type: a maintenance issue, information request, or inspection finding. Match the type to what the photo and note document.',['Maintenance record']);
add('hoaPriority|hiPriority|hoaFilterPriority','Set or filter maintenance priority. Routine, High, Emergency, and Monitor support different follow-up needs. This is the property workflow’s priority, separate from the capture’s Standard/Urgent field. Selecting a priority does not itself dispatch a contractor.',['Priority','Urgency']);
add('hoaArea|hiArea','Choose the maintenance category matching the photograph. Use it consistently so records for the same kind of work can be found together.',['Category']);
add('hoaDirected|hiDirected','Name the person expected to answer this information request or follow-up. Add clear instructions in the description. Entering a name alone is not proof that the person received a notification.',['Assignment']);
add('haCommunityName|hcCompanyName','Enter the community or management-company name used to identify these property records. Check spelling before saving so the team can recognize the organization.',['Community']);
add('haCommunityAddress|hcAddress','Enter the property’s full address. This identifies the community; individual asset locations and photo GPS provide more specific evidence.',['Community','GPS']);
add('haAddCommunity|hcCreate','Create the community using the entered name and address. It will be available for property photos, asset records, and inspection routes. Review details before saving.',['Community']);
add('haName','Name the specific physical asset, such as North entrance monument or Pool gate. Use a stable name that the next inspection can reuse.',['Asset']);
add('haType','Describe the kind of physical asset, such as a light, gate, fence, or playground. The type helps group similar assets.',['Asset']);
add('haLocation','Describe the exact position of the asset within the property. Include landmarks or direction so another person can find and photograph the same object.',['Asset']);
add('haPhoto|hapPhoto|hoaItemPhoto|hvsPhotos','Choose clear documentation photos for this asset, maintenance item, or inspection stop. Include an overview and close-up when useful. Review the selected files and note before saving them to the record.',['Evidence']);
add('haNote|hapNote|hoaItemPhotoNote|hvsNote','Describe the condition visible in these property photos, what changed, and any follow-up needed. Keep the note tied to the photographed asset or visit stop.',['Evidence']);
add('haCreate','Save the physical asset record and its required identity photo. Verify community, name, type, location, and condition first. The identity photo is the starting point for future condition history.',['Asset','Evidence']);
add('hapType|hoaPhotoStage','Choose the role of this documentation photo, such as initial condition, damage, work in progress, completed work, or final verification. This allows the timeline to distinguish evidence before and after work.',['Photo purpose','Verification']);
add('hapAdd|hoaAddPhoto','Attach the selected documentation photo and note to the existing history. Check purpose/stage before saving. This adds evidence; it does not automatically mark the maintenance work complete.',['Evidence','Timeline']);
add('hirName','Give the inspection route a clear reusable name, such as Monthly common-area inspection. The route becomes a template for later guided visits.',['Inspection route']);
add('hirInstructions','Describe how to walk the route and what inspectors should look for. Include the start point, direction, access needs, and safety considerations relevant to the property.',['Inspection route']);
add('hirStops','Enter one inspection stop per line. Use the format shown beside the field: the stop name followed by the requested photo views. These become the ordered stops and photo requirements of the route.',['Inspection route']);
add('hirCreate','Save the route’s community, name, instructions, and ordered stops. Review that each stop has clear photo requirements before starting a visit.',['Inspection route']);
add('hvNew','Start a guided property visit using an available inspection route. Review the community and route first, then work through stops in order and provide the requested photos.',['Property visit','Inspection route']);
add('hvsComplete','Save the photos and note for the current stop, then mark that stop complete. Check that all requested views are present before moving on. Completed stops form the photographic visit record.',['Property visit','Evidence']);
add('hoaFilterStatus|hiStatus','Filter records by status or update the maintenance item’s workflow stage. Completed means the work has been verified, not merely photographed. Supply the required completion details before saving a completed record.',['Status','Verification']);
add('hoaSearch','Search maintenance titles, descriptions, communities, or categories. Combine the search with the community, status, priority, and type filters to narrow the records.',['Filter']);
add('hoaSearchBtn','Apply the entered maintenance search and current filters. Clear the search or broaden filters if a known record is missing.',['Filter']);
add('hoaShowClosed|hrClosed','Include completed and canceled records in this view or report. Turn this off to focus on active work. Showing a closed record does not reopen it.',['Status']);
add('hiDescription','Explain the maintenance issue, what the photo demonstrates, and the requested work. Include relevant measurements, access details, and questions for the assigned person.',['Maintenance record']);
add('hiAssignee|hcManager','Identify the responsible person or community manager. Use a recognizable name and keep it consistent across records. Check the workflow’s notification status separately.',['Assignment']);
add('hiTarget','Set the target completion date for the maintenance work. Review overdue items against this date. A target date is a plan, not proof of completion.',['Target date']);
add('hiBudget|hrBudget','Choose or filter the budget source, such as operating funds or reserves, using the available choices. Review funding before approving or reporting work.',['Budget']);
add('hiEstimated|hiActual','Record the estimated or actual cost, as labeled. Use an estimate before work and verified final costs after completion. Keep supporting invoices or photos with the record where appropriate.',['Budget']);
add('hiApproval','Record the board-approval stage. Requested, approved, rejected, or deferred represent distinct decisions. Update this only when you have evidence of the decision.',['Approval']);
add('hiCompletedBy','Enter who completed the work. This is required before a maintenance item can be saved as completed. Verify the final photos before closing the item.',['Verification']);
add('hiCompletion','Enter the actual completion date. Keep it distinct from the target date and check it against the completed-work evidence.',['Verification']);
add('hoaItemSave','Save the edited maintenance fields. Review status, responsibility, target date, approval, and costs together. Completion requires the responsible person and evidence that the work was finished.',['Maintenance record']);
add('hoaCompletionName','Enter the person expected to submit completion photos. The resulting link lets that person provide evidence for this maintenance item.',['Completion link']);
add('hoaCompletionCreate|hoaCompletionUrl|hoaCompletionCopy','Create or copy the completion-photo submission link. Share it with the person doing the work, verify the returned images, and update the maintenance record yourself. Creating or copying a link does not deliver it.',['Completion link','Verification']);
add('hcMemberEmail','Enter the existing team member’s email address to add them to the management company. Confirm the account and organization before granting access.',['Account access']);
add('hcAddMember|hcSaveCompany','Save the entered company/team change. Review the management organization and member identity first; access to property records should match the person’s role.',['Account access']);
add('hoaReadAll','Mark the displayed property notifications as read. This clears unread indicators; it does not resolve the related maintenance records.',['Notification']);
add('hoaReportPdf|hoaReportWord|hoaPrintReport|concreteReportPdf|concreteReportWord|concretePrint|pavingJobPdf|pavingJobWord','Prepare or print the photo-evidence report for the selected community/project and filters. PDF preserves the finished layout; Word allows further editing. Open and inspect the output before distribution, including photos, notes, locations, and dates.',['PDF','Word','Evidence']);
add('concreteReportJob','Filter the concrete evidence report to the relevant project. All Projects includes records across projects; choose a specific site before exporting a customer report.',['Project','Filter']);
add('concreteReadiness|pavingReadiness','Review the evidence checklist for the selected job. Missing or unverified items indicate gaps to resolve before export. Readiness is a summary of recorded evidence, not independent certification of the work.',['Evidence','Verification']);
add('newJobName','Enter a recognizable name for the job or site. Use the same job for photos documenting the same piece of work.',['Job']);
add('newJobNumber','Enter your organization’s job reference when available. This helps distinguish projects with similar names.',['Job']);
add('newJobCustomer','Enter the customer or client for this job. Check the name before using it in reports.',['Job']);
add('newJobAddress','Enter the job-site address. It provides project context; each photo’s GPS and address should still be reviewed.',['Job','GPS']);
add('createJobBtn','Create the job from the entered name, number, customer, and address. Select it when organizing or capturing its photographs.',['Job']);
add('timelineBtn|jobStatusBtn','Open the selected job’s photographic timeline or change its job status. Review the date sequence and associated evidence. A job’s completion status is separate from individual maintenance or extra-work records.',['Timeline','Status']);
add('filter|mapTopic','Filter the library or map by a topic. All Topics shows the full eligible set. Filtering changes what you see, not the topics already attached to photos. Filters include topics on existing saved photos, even after the selectable Capture topic list was cleared. This does not restore old choices to Capture.',['Topic','Filter']);
add('photoSearch','Search saved notes and supporting details such as jobs, customers, addresses, topics, dates, or defects. Use specific words and combine them with filters to locate evidence.',['Filter']);
add('photoSearchBtn','Run the library search using the current words, topic, job, and additional filters. Check the result count before selecting photos.',['Filter']);
add('photoSearchClear','Clear the library search and refresh the results. This does not delete records or notes.',['Filter']);
add('searchFrom|searchTo','Limit results to the date range shown. Set either endpoint or both. Check the date range if an older or newer capture is absent from the results.',['Filter']);
add('searchMissingAddress','Show captures that need address information. Open them to correct the address or retry a lookup where usable GPS exists.',['Geocoding','Filter']);
add('sendPhotoSelection|sendPhotoSelectionSummary','Open Select Photos to reveal the Photo Library in Send. It starts collapsed so documents and other Send sections remain easy to reach. Select or unselect Photo Notes, then close the section without losing your selection. The selected count remains visible. Closing the library does not share, download or delete anything.',['Selection','Photo Library']);
add('closeSendPhotoSelection','Collapse the Photo Library and return to Select Photos. Your selection is kept for sharing, downloading or creating a customer approval package.',['Selection','Photo Library']);
add('sendJobFilter|sendTopicFilter','Narrow the Send Photo Library by job, topic or both. Both filters must match when combined. All Jobs and All Topics remove their respective filters. Changing filters does not change selections. Check the counts for selected records inside and outside the filters before sharing.',['Job','Topic','Selection']);
add('selectAllSendCaptures','Add every currently matching Photo Note to the selection. Records outside the filters are not newly selected; any already selected outside them remain selected. Clear All clears the entire selection. Review the total and outside-filter count before sharing.',['Selection','Job','Topic']);
add('selall','Select all photos offered by this current view for the next action. Review the selected count and filters; Select All does not automatically mean every record in your account.',['Selection']);
add('selnone|clearSendSelection','Clear the current selection. This does not delete photos. Select the intended photos again before applying a batch change, sharing, or building a document.',['Selection']);
add('capchk|sendchk','Include or exclude this photo from the current selection. Selected photos are the scope of batch changes, document creation, deletion, or sharing. Always verify the selected count.',['Selection']);
add('compareSelected|pairbtn','Select exactly two photographs, then compare them or create a Before/After pair as labeled. Check which image represents the earlier condition. Comparison does not alter the underlying originals.',['Before/after','Selection']);
add('cmpSideBtn|cmpOverlayBtn|cmpOpacity','Choose side-by-side or overlay comparison. In overlay mode, move the transparency slider to inspect differences. Check camera alignment and perspective before judging a change.',['Before/after']);
add('classifybatch|classifybtn','Ask the available AI classifier to suggest a defect type and severity for the selected evidence. A connection and enabled account feature are required. Review and correct results; AI output is not a verified diagnosis.',['AI','Severity']);
add('ovtype','Choose the visible defect type. Correct an AI suggestion when it does not match the evidence. Use Other or No Defect when appropriate.',['AI','Defect']);
add('ovsave|overridebtn','Open or save a manual correction to defect type and severity. Base the correction on the photograph and site knowledge, then check the updated result.',['Defect','Severity']);
add('bulktopic|applytopic|replacetopic','Choose a topic for the selected photos. Add Topic retains their existing topics; Replace Topics replaces their topic assignments with the selected one. Check the selection and the action before applying it.',['Topic','Selection']);
add('groupsel|newgroupname|addtogroup','Choose an existing document, or enter a new document title where offered, then add the selected photos. Document copies can be ordered and captioned separately from the library originals.',['Document','Selection']);
add('openAnnotationEditing','Open the selected photos for batch annotation work inside Library. The current selection is retained.',['Selection','Markup']);
add('batchAnnotationMode|singleTemplateMode','Add keeps existing markings and appends the template. Replace removes all existing markings and uses only the template. Overlapping positions can obscure text; preview each photo. Up to 20 markings per photo.',['Template','Markup']);
add('batchAnnotationConfirm','Confirm that Replace removes all existing markings from every selected photo. Leave unchecked to prevent replacement, or choose Add to preserve existing markings.',['Markup','Selection']);
add('applyBatchAnnotations','In Edit, select photos, choose a template and Add or Replace. Replace requires explicit confirmation. Apply saves editable markings to all selected owned photos together; an unavailable photo or exceeded limit prevents the whole batch. The confirmation reports the actual saved count. Original photo pixels and thumbnails stay unchanged. Preview / Adjust Photo shows the saved markings.',['Template','Markup','Original','Selection']);
add('batchAnnotationPhoto|previewBatchAnnotations','Choose an updated photo and open Mark Up Photo to preview its saved markings. Check placement and text. Adjust any item and Save Changes to retain adjustments; Back leaves already-applied batch markings saved. You can also open Mark Up Photo on each card in Edit.',['Markup','Original']);
add('annotationTemplateName|saveAnnotationTemplate','In Mark Up Photo, arrange text, labels, boxes and arrows, enter a unique name, and Save as New Template. This saves a private, reusable template for your account across shared editions, not changes to this photograph. Save Changes separately to retain photo markings. Choose the saved template in single-photo or batch Edit and use Add or confirmed Replace. Templates use relative placement; review every destination photo. Date, address, GPS, Topic, Dimensions and Defect resolve from each destination photo, while custom text is reused literally. Up to 20 markings; names up to 80 characters.',['Annotation template','Markup','Original']);
add('deleteAnnotationTemplate','Delete the selected saved template from your account after confirmation. Built-in presets cannot be deleted. Markings already applied to photos remain; deleting a template does not change photographs.',['Annotation template','Markup']);
add('batchTemplate|singleTemplate','Apply Saved or Preset Template applies a reusable group of markings. Choose a built-in preset or a named template under My Annotation Templates. Add Individual Marking adds one label, text item, box or arrow at a time. Address and GPS markings use saved photo details. When these are missing, individual markings are not added and templates skip those fields with an explanation. Add an address through Edit Address before reopening markup. GPS requires coordinates saved with that photo. Older saved empty markings can be selected and deleted; the marking count includes those saved entries. Review the resulting placement on each photo; a template may not fit photos with different framing.',['Template','Markup']);
add('deleteJobBtn','Choose a specific job in Current Job, then Delete Job and confirm. Only the job is deleted. Its photos, tickets and other saved records remain in the account without that job assignment. Choose Unassigned to find its photos afterwards. Deletion cannot be undone; create a new job and assign records again if needed.',['Job','Selection']);
add('data-gauge-photo-details','Show the complete reviewed instrument details linked to this photo, including observed time and longer Notes. Key readings remain visible in the compact summary. The same fields appear beneath the correct photo in PDF and Word documents in the relevant industry editions.',['Camera reader','Document']);
add('runBatch','Move the selected photos to the chosen job. Add photos to a document with the separate Add Selected to a Document control. Review the selected count before applying; unrelated photos should be deselected first.',['Selection','Job']);
add('concreteAreas|concrete-area-button|areaBack','Open the photo-linked patio/foundation area workspace. This tool is available in Concrete Pro. Select the relevant source photo, trace or locate the area, and record measured dimensions with their source. Saved areas appear on that Library photo and in document previews and PDF/Word exports. View / Edit Saved Areas opens that photo’s measurements. Map estimates and user-entered dimensions remain distinct. Phone map actions use two columns with wrapped readable labels. This documents a proposed or existing area; it is not a certified survey.',['Area','Measurement']);
add('openmap|gotoMap|mapGroup','Open the job-site map or filter it to a document. Located photos appear in context. Missing GPS can prevent a photo from appearing at the correct site. Trace only the intended area and review units before reporting measurements.',['GPS','Area']);
add('rotccw|rotcw|flipphoto','Rotate the photo 90 degrees in the indicated direction or flip it horizontally. Check orientation afterward. The original is retained so saved edits can be restored.',['Original']);
add('editdims|measureBtn|doMeasure','Open measurements or run assisted measurement. Use a known reference visible in the same plane as the subject, enter its real size and units, then review the estimate. Perspective and an incorrect reference can produce inaccurate dimensions.',['Measurement','Reference']);
add('dimLength|dimWidth|dimDepth|reflen','Enter the dimension identified by this field. Confirm the unit alongside it. Reference length must be a known real-world length visible in the source photo. Use verified site measurements when precision matters.',['Measurement','Reference']);
add('dimLengthUnit|dimWidthUnit|reflenunit','Choose the unit matching the entered measurement. Feet and inches are not interchangeable; review the converted values before saving or exporting.',['Measurement']);
add('dimShape','Choose the shape used to calculate area. A rectangle and circle use different formulas; use Irregular or a reviewed manual area where the subject does not fit either.',['Area']);
add('dimArea','Review the calculated square-foot area or enter a measured override where supported. Confirm dimensions and shape before relying on the result.',['Area','Measurement']);
add('measureConfirm','Confirm that you have reviewed the assisted measurement. Low-confidence estimates can be excluded from reports until you confirm them. Confirmation records your review; it does not independently verify accuracy.',['AI','Measurement']);
add('saveDims','Save the reviewed dimensions, units, shape, and area with this photo. Check the result and any confirmation requirement before including measurements in a report.',['Measurement']);
add('concrete-ticket-file','Choose a clear batch-ticket or specification photo to link to this concrete evidence. Review readable mix and delivery details rather than inferring them from the concrete appearance.',['Specification']);
add('edittitle|photoTitle*|savephototitle','Enter and save a short descriptive photo title. Name the subject and condition so it can be recognized in the library and exported documents. Export preserves the entered title, including Untitled. A blank title becomes Photo 1, Photo 2, and so on in the document; location remains separate. This changes the title, not the photo file.',['Photo note']);
add('edittopics|savetopics','Choose the topic checkboxes for this photo and save them. Multiple topics may be used. Review which labels are being retained or removed before saving.',['Topic']);
add('editnote|savenote','Open or save the text note attached to the photo. Correct dictated text and retain the details that explain the visible evidence. Saving a note does not apply image markup.',['Photo note']);
add('stampbtn|stampSave','Open the markup editor or save the current annotations. Use arrows, shapes, and text to call attention to visible evidence. Save Changes before leaving; Download Marked Photo creates a file but is not a substitute for saving the edit.',['Markup','Original']);
add('stampCopy','Download the currently marked photo for use outside PhotoNotes. Review the output. A downloaded marked photo and saved annotations in the app are separate results.',['Markup','Download']);
add('applySingleTemplate','Apply the selected annotation template to this photo. Add keeps existing markings; Replace removes them and requires confirmation when markings exist. Check every item’s placement and text, then Save Changes to retain the result.',['Template','Markup']);
add('ovText|ovFont|ovSize|ovThick|ovColorPick|ovOutline','Adjust the selected annotation’s text, font, size, line thickness, color, or outline as labeled. Keep labels legible and avoid obscuring the evidence. Save Changes when the markup is complete.',['Markup']);
add('ovDelete|issueMarkupDelete','Delete only the selected markup item. Use Undo where available if removed by mistake. This does not delete the underlying photograph.',['Markup']);
add('cropbtn|cropApply|cropBack|cropCancel','Open the crop tool, frame the relevant area, and apply the crop. After applying, only the cropped photo refreshes. Your filters, selected photos and position in the original workspace are retained. Cancel or Back returns without cropping. Review the result before exporting. The original photograph is retained for Restore Original.',['Crop','Original']);
add('restorebtn','Restore the first uploaded photo and remove its saved visual edits after confirming. Review the restored result. Text notes and other record details remain separate.',['Original']);
add('evidencebtn','Inspect the photo’s evidence details, original-file fingerprint, and recorded history. Review who captured it and subsequent changes. A fingerprint checks file identity; it does not prove that the pictured event or statement is true.',['Fingerprint','Evidence']);
add('photoViewerReset','Reset zoom and panning to view the full photo. This changes the viewer only, not the saved photograph.',['Original']);
add('delbtn|delall|organize-delete-capture|send-delete-capture','Delete the selected photo records or all records in the stated scope, as labeled. Read the confirmation carefully. This removes saved evidence, unlike clearing a selection or removing a document copy.',['Selection','Original']);
add('unpairbtn','Remove the Before/After association between these photos. The photos remain separate records in the library.',['Before/after']);
add('areaPhoto','Choose the source photo for the area record. The saved outline and dimensions should describe the photographed patio, foundation, or other intended work.',['Area']);
add('areaName','Name the measured/proposed area, such as Backyard patio. Use a name that identifies its purpose and position at the site.',['Area']);
add('areaPhotoLocation|areaMyLocation','Center the map using the selected photo’s GPS or this device’s current location, as labeled. Verify the displayed site before drawing. Current device location may differ from where an imported photo was taken.',['GPS']);
add('areaTrace|drawArea|drawSpan','Start tracing an area boundary or measuring a span. Add points in the intended order. Close the outline for an area, then review its shape and measurement source. Map tracing is approximate. Tap a new position for each additional corner; dragging a corner changes its position without adding a corner.',['Area','Measurement']);
add('areaUndo','Remove the most recently added corner from the active outline. Review the remaining points before continuing.',['Area']);
add('areaClear','Clear the draft outline and start again. Check whether the action affects the current draft or a saved record before confirming.',['Area','Draft']);
add('areaFinish|drawFinish','Finish the current area outline or span. Review the boundary and units before saving or attaching it to a report.',['Area','Measurement']);
add('areaLength|areaWidth','Enter the verified real-world dimensions of the area using the units displayed. Check length and width against the site or plans.',['Area','Measurement']);
add('areaMethod','Identify the source of the measurement, such as manual site measurement or map-based estimate. This provenance explains how the dimensions were obtained.',['Provenance','Measurement']);
add('areaNotes','Document who measured the area, when, and any assumptions, layout details, or source plan. This makes later review of the dimensions possible.',['Provenance']);
add('areaSave','Enter an area name, then save the reviewed area outline, dimensions, method, and notes linked to the selected photo. Save errors are brought into view so you can correct the problem. Check the source and site before using the area in a proposal. If you have valid field dimensions and an unfinished one- or two-corner outline, you can confirm saving the dimensions alone and discarding those unfinished corners.',['Area','Evidence']);
add('areaNew','Start a separate new area record. Use a distinct name and source photo if it documents a different part of the site.',['Area']);
add('zn-edit|zn-rename|zn-attach|zn-del','Edit the zone’s points, rename it, attach it to a document, or delete the zone as labeled. Deleting a map zone is different from deleting its associated photos. Review the target zone before applying the action.',['Area','Document']);
add('sendformat|document-delivery-format|export-res|export-fmt','Choose the output type or image quality. PDF is a finished layout; Word is editable. Regular PDF and Word documents use the same metadata order and readable body size beneath each photo; page breaks can differ. Markdown + Photos is a ZIP with text and images. Smaller image exports reduce size but can lose fine detail. These settings do not lower the resolution of the stored original.',['PDF','Word','Markdown','Resolution']);
add('sharephotos','Prepare the selected photos and use this device’s share destinations. Confirm the selected count and destination, then complete the operating system’s share sheet. Canceling or closing it is not proof of delivery.',['Share sheet','Selection']);
add('senddocument','Download an export in the selected format. Wait for preparation, check the browser’s Downloads, and open the file to confirm its content before attaching it elsewhere.',['Download','PDF','Word']);
add('sendshortcuts|shortcutSelect','Open saved delivery shortcuts or choose a destination. Shortcuts store your own email, SMS, HTTPS website, or Ramo destination. Select the photos first. Some destinations prepare a message but require you to attach the downloaded file yourself.',['Shortcut','Share sheet']);
add('shortcutName','Name the saved destination so it is easy to recognize, such as the customer or project team. The name is a label, not the delivery address.',['Shortcut']);
add('shortcutType','Choose the delivery method. Email and SMS prepare a message; HTTPS opens a website destination; Ramo uses the grouped submission workflow when authorized.',['Shortcut','HTTPS']);
add('shortcutTarget','Enter the email address, phone number, or HTTPS URL appropriate to the chosen shortcut type. Verify the destination carefully before using it. A Ramo shortcut uses the configured integration rather than a pasted secret token.',['Shortcut','HTTPS']);
add('shortcutCreate|shortcutSave','Save the named destination for reuse by your account. Confirm its type and target first. Creating a shortcut does not send the current photos.',['Shortcut']);
add('shortcutManageLinks','A shortcut creates a shared document link for email or text. If your account reaches 100 active links or 100 MB, open Manage shared links and revoke a link you no longer need, then tap Send again. Revoking prevents recipients from downloading through that link. Links otherwise expire after seven days. Preparation errors explain whether document creation or shared links failed.',['Shortcut','Document link']);
add('shortcutDelete','Delete this saved destination after checking its name. This removes the shortcut, not previously shared files or photo records.',['Shortcut']);
add('sendToRamo|ramoIntakeSend|ramoSend','Prepare selected photos as one grouped submission to Ramo Optimizer. Enter a title and description, review captions and photos, then submit. Read the receipt: received means the receiver confirmed all attachments; a queued or failed status needs follow-up. Each send is a separate submission.',['Ramo','Receipt']);
add('ramoIntakeHistory','Review previous grouped submissions, delivery status, and available receipts. Retry a failed/pending submission using the existing record to avoid duplicates. Verify received status rather than assuming a button click completed delivery.',['Ramo','Receipt']);
add('ramoTitle','Give the grouped submission a meaningful title identifying the proposed change or evidence. A title is required; keep your selected photos if the form requests a correction.',['Ramo']);
add('ramoDescription','Describe what changed, why the grouped photos matter, and the requested review. Keep the scope limited to the photos included in this submission.',['Ramo']);
add('ramoCaption*','Explain this photo’s role in the grouped submission. Captions should identify the condition, location, and change supported by the image. Review all attachments before submitting.',['Ramo','Caption']);
add('approvalTitle','Name the customer review package so the recipient can recognize the work. Check the selected photos before creating the link.',['Approval']);
add('approvalMessage','Write instructions for the customer, including what to review and any question needing a response. This message accompanies the review link.',['Approval']);
add('organizeJobSection|organizeFindSection|organizeWorkSection','Open or close Projects, Search, or Selected PhotoNotes in Library. Closing a section hides its controls without clearing selections or filters.',['Selection','Project','Topic']);
add('librarySelectAll|libraryClearSelection','Select every PhotoNote currently shown in Library, or clear the current photo selection. Clearing a selection does not delete or change any PhotoNote.',['Selection','Library']);
add('jobFilter|createJobBtn|libraryGroupFilter|createProjectGroup','Filter the Library by project and, when a project is selected, by one of its groups. New Project creates an organizing project. New Group creates a group inside the selected project. A PhotoNote may belong to more than one project and more than one group.',['Library','Project','Group']);
add('libraryFilters|librarySavedSearches|photoSearch|photoSearchClear','Search titles, notes, and saved details. Filters open topic, date, missing-address, Favorite, and Flagged choices. Saved Searches opens reusable search choices. Clear Filters restores the full Library.',['Library','Filter']);
add('libraryAssignProject|libraryAssignGroup|libraryAssign|libraryCreateAndAssign','After selecting PhotoNotes, add them to an existing project and optionally to a group within that project, or create a new project. A successful assignment clears the photo selection.',['Selection','Project','Group']);
add('libraryNewProjectName|libraryCreateProjectConfirm','Enter a unique, recognizable project name and create it. If you began from selected PhotoNotes, they are added to the new project after creation.',['Project','Selection']);
add('libraryNewGroupName|libraryCreateGroupConfirm','Name a group inside the selected project. Groups organize related PhotoNotes within that project.',['Project','Group']);
add('requestProjectPhotos','Choose a project first, then open Photo Requests with that project already selected. Define the recipient, instructions, and required photo views before creating the private submission link.',['Photo Request','Project']);
add('shareApproval|shareExistingApproval','Share the customer review link through the device sharing menu. Choose a destination and complete delivery yourself. Canceling does not send it. When device sharing is unavailable, the link is copied if clipboard access is allowed; Copy Link remains available as a fallback. Sharing does not mean the customer approved the photos.',['Approval','Share sheet']);
add('createApproval','Create a private, expiring review link for the selected photos. Review the package before sharing the URL. Creating the link does not send it or mark the photos approved.',['Approval','Selection']);
add('approvalUrl|copyApproval|copyExistingApproval','Copy the review URL and send it to the intended customer through your chosen channel. Treat it as a private link. Check expiration and recorded responses in PhotoNotes. Anyone holding an active customer review link can view the package and submit a response without a Photo Notes account.',['Approval']);
add('billing-checkout','Open the configured Stripe checkout for this offer. Review the provider, description, quantity, and price before completing payment. Opening checkout does not complete a purchase.',['Checkout']);
add('gtitle|gdtitle','A nonblank document title is required. The title field starts empty; no default name is assigned. Enter the document title that will appear in the generated report. Identify the job or subject and the report purpose. Save an edited title before exporting.',['Document']);
add('gdesc|gddesc','Enter the report subtitle or description. Explain the scope and context of the selected evidence. Keep it distinct from individual photo captions.',['Document','Caption']);
add('documentPhotoSource','Optionally choose a job or topic to load its photos for review directly in Create. All matching photos start selected. Uncheck photos you do not want. The reviewed photos replace the current Organize selection for this document only; they do not change the saved job or topic assignments. Choose Use current Organize selection to keep the existing workflow or create an empty document when nothing is selected. A source with no selected photos cannot be submitted.',['Document','Selection','Topic','Job']);
add('data-document-source-photo','Include or exclude this photo from the new document. Review its image, title, address and capture date. This changes only the proposed document contents, not your library or Organize selection.',['Document','Selection']);
add('captureSaveToJob|captureJobChoice|captureJobSave|captureNewJobName|captureJobCreate|captureJobUnassigned|captureJobCancel','After taking a photo or entering notes, Save to Job lets you select an existing job, create a named job, or save without a job. This is optional. Save and Send/Share remain available without job selection. Cancel preserves the draft. Creating a job requires a connection; if it fails, keep the draft or save unassigned. Only this capture receives the selected job. Specialist capture details remain attached.',['Job','Capture']);
add('newDocument|gtitle|gdesc|documentSetupPreset|useDocumentSettings|saveDefaultSettings|savePresetSettings|cancelNewDocument|newDocumentType|newDocumentOrientation|newDocumentPhotoLayout|newDocumentFont|newDocumentAccent|newDocumentHeader|newDocumentHeaderText|newDocumentFooter|newDocumentFooterText|newDocumentNumbers|newDocumentPagePosition|newDocumentCover|newDocumentCompany|newDocumentTemplate|newDocumentStarterTemplate','Create starts with a required document title and Document Settings. The default settings appear first. A named preset replaces those settings when selected. Use for This Document applies settings only to this document. Save as Default changes the starting settings for future documents. Save as Preset stores a named shortcut. Layout and Style controls document type, orientation, photos per page, font, accent color, headers, footers and page numbers. Cover Page adds a separate title page and contains company branding. Word Template is optional. After settings, choose at least one PhotoNote before saving the new document.',['Document','Document Settings Preset','Default']);
add('newDocumentTopic|newDocumentJob|newDocumentPhotoSearch|selectAllDocumentPhotos|clearDocumentPhotos|data-document-source-photo|backDocumentSetup|gcreate','Choose at least one saved PhotoNote for the new document. Search, Filter by Topic and Filter by Job narrow the choices together. Topic choices include topics saved on older photos; job choices come from the saved photos. Changing filters keeps photos already selected, including hidden selections. Select All adds only matching PhotoNotes. Clear All clears the selection. Back returns to Document Settings without creating a document. Save New Document creates the named document only after the title, settings and photos are ready.',['Document','Photo note','Selection']);
add('documentSearch|createDocumentSort|glist','Available Documents lists named saved documents with their PhotoNote count and last modified date. Search filters by title. Sort orders A to Z by default, Z to A, Newest First or Oldest First. Open Document continues editing without changing Library membership.',['Document','Last Modified']);
add('sendSource|sendDocumentSearch|sendDocumentSort|sendDocs|data-use-document|data-edit-document|data-send-options','Choose Documents or PhotoNotes beside Send. Documents lists only named documents containing at least one PhotoNote. Search filters by title. Sort orders A to Z by default, Z to A, Newest First or Oldest First. Use This Document reveals its Share, Download and Print choices. Edit Draft opens the document in Create.',['Document','Share sheet','Last Modified']);
add('gopen','Open the document composer to review details, photos, captions, order, branding, preview, and export settings. Changes to document copies do not replace the library originals.',['Document']);
add('editTitle|saveTitle','Edit or save the document title. Check the saved heading in the preview before exporting.',['Document']);
add('editDesc|saveDesc','Edit or save the document subtitle/description. Review the preview so the context is accurate for the included photos.',['Document']);
add('greverse','Reverse the order of photos in this document. Review the result before export, particularly where the report tells a before-and-after story. Library order is unaffected.',['Document','Before/after']);
add('gcaption|gsavecaption|ewrcap|ewrcapsave','Edit and save the caption for this document/evidence copy. Explain what the photograph demonstrates. A caption belongs to this presentation of the photo and is separate from the library note.',['Caption']);
add('gup|gdown','Move this document photo one position up or down. Arrange photos in the sequence that best explains the evidence. This does not reorder originals in the library.',['Document']);
add('documentCompanyName','Enter the company name used on this report. Review spelling and identity before saving branding text.',['Branding']);
add('documentHeaderText','Enter optional header text for the report. Enable Header in Layout if it should appear in exported pages.',['Branding']);
add('documentFooterText','Enter optional footer or contact details. Enable Footer in Layout if this text should appear in the exported pages.',['Branding']);
add('saveDocumentBranding','Save the company, header, and footer text. Review the document preview and the relevant layout toggles before exporting.',['Branding']);
add('documentLogoFile','Upload the company logo using an accepted image format. Check that the image belongs to the organization and is legible in the preview. This affects report branding, not photo evidence.',['Branding']);
add('documentTemplateFile','Import a .docx template for this document. It must include {{PHOTO_NOTES_CONTENT}}; optional placeholders include {{TITLE}}, {{DESCRIPTION}}, and {{COMPANY_NAME}}. Check the generated preview and exported file for placement and page breaks.',['Template','Word']);
add('document-remove-asset','Remove the uploaded logo or Word template identified by this control. Removing a template returns the document to its regular layout. The photos remain in the document.',['Template','Branding']);
add('documentType','Choose Standard Document or Proposal Exhibit for this document.',['Document']);
add('documentOrientation','Choose portrait or landscape pages for the preview and exported document.',['Document']);
add('documentFont','Choose the document font. Review readability in the preview and exported Word or PDF file. The document font does not change photo contents.',['Document']);
add('documentPhotoLayout','Choose how many photos appear on each page and whether two-photo or three-photo pages use a vertical or horizontal arrangement. Check captions and page breaks in the preview.',['Document','Resolution']);
add('documentAccent','Choose the report’s accent color. Keep body text readable and inspect the exported output. This affects report decoration, not the original photos.',['Branding']);
add('documentCover|documentHeader|documentFooter|documentPageNumbers','Include or omit the cover page, header, footer, or page numbers as labeled. Review the preview and save the layout before export. Header/footer text is configured separately in Branding.',['Document','Branding']);
add('documentPagePosition','Choose whether page numbers appear at the bottom left, center, or right. One-page documents do not show a page number.',['Document']);
add('saveDocumentLayout','Save the current typeface, photo arrangement, accent, and page-element toggles. Preview changes alone are not proof they were saved. Export and inspect the final file.',['Document']);
add('documentPreview','Review the assembled document, including title, descriptions, photos, captions, branding, and page order. Complete saved Before/After pairs appear together in the main page preview, irrespective of the single-photo page setting. The preview helps find omissions; open the downloaded PDF or Word file for final verification.',['Document','PDF','Word']);
add('ewrNew','Create an Extra Work Record linked to the job. Document the cause, added work, notification details, and supporting photos before seeking review. PhotoNotes records evidence; it does not independently approve contract changes.',['Extra work']);
add('ewrOther','Describe the extra-work reason when the listed reasons do not fit. Tie it to the condition shown by the photos.',['Extra work']);
add('ewrCustomer','Identify the customer or client whose job the added work concerns. Confirm that the job and customer match before saving.',['Extra work']);
add('ewrNname|ewrNcompany|ewrNnotes','Record the person notified, their company/role, and what was communicated. This records your account of the notification; it is not an independent delivery receipt.',['Extra work','Receipt']);
add('ewrStatus','Choose the extra-work record’s current workflow status. Keep pending, approved, completed, or other offered stages consistent with the evidence and actual decision.',['Extra work','Status']);
add('ewrSave|ewrSaveEdit','Save the Extra Work Record and reviewed supporting details. Check the job, reason, explanation, notification information, and evidence photos. Saving is not customer approval.',['Extra work']);
add('ewrExport','Export this Extra Work Record as a PDF for review. Check captions, notification details, and attachments before distribution.',['Extra work','PDF']);
add('ewrDelete','Delete this Extra Work Record after reviewing the confirmation. Removing the record is different from deleting a photo from the library.',['Extra work']);
add('ewrphotodel|ewrrm','Remove this photo attachment from the extra-work record. Verify the target attachment before confirming. Library originals are separate from this record’s attachments.',['Extra work','Original']);
add('alignTake','Take the After photo from a matching viewpoint. Match camera height, direction, landmarks, and framing to the selected Before image. Use the overlay to compare alignment.',['Before/after']);
add('alignOpacity','Adjust the After-photo transparency over the Before photograph after capture. The native camera does not show this overlay. This is a visual alignment aid and does not correct perspective automatically.',['Before/after']);
add('alignNote','Describe the completed work or condition shown by the After image. Keep the note specific to this comparison.',['Before/after']);
add('alignSave','Save the reviewed After photo, note, and association with the chosen Before photo. Verify image alignment and chronological meaning before saving.',['Before/after']);
add('readerRead|ticketRead','Read the source photograph using the configured scanner. Wait for the result, then check every extracted value against the visible source. If reading fails or confidence is low, correct fields manually or retake the image.',['AI','Camera reader']);
add('readerSave|ticketSave','Save the reviewed reading or ticket with its source photo. Confirm dates, quantities, units, identifiers, and job association first. A scan result is not saved until this step succeeds. Use Open in Photo Library on a saved reader record to create or open its linked Photo Note.',['Camera reader','Evidence']);
add('tkJobLink','Associate the ticket with the correct job. This determines where delivery evidence and quantities appear in job reports.',['Job','Specification']);
add('cr_*|tk*','Review this extracted field against the source photograph and correct it before saving. Dates, material names, ticket numbers, weights, temperatures, and units must match the readable source. Leave unknown values blank rather than guessing.',['Camera reader','AI']);
add('issueFab|myIssues|issuesBack|issueUpdates','Open application issue reporting or your submitted issue history. The floating Report Issue button is hidden while its dialog is open so it cannot cover Send Issue Report. Close the dialog to return to the page. Your submitted issue history shows your report and its status. Automatic voice diagnostics are retained for troubleshooting and excluded from the displayed description. Use this for a PhotoNotes software problem. Describe the exact screen, action, expected result, and actual result; road/property records are separate workflows.',['App issue']);
add('issueType','Choose the kind of application report, such as a bug/problem or idea. A reproducible failure and a feature suggestion should be described separately.',['App issue']);
add('issueDescription','Describe what you did, what you expected, and what happened. Include the screen and steps to reproduce. Review dictated words before sending. Do not include passwords or secret keys.',['App issue']);
add('issueFrequency','Choose how often the problem occurs. If it happens intermittently, include the circumstances and any reliable way to reproduce it.',['App issue']);
add('issueResultScreenshot|issueResultChoose','Optionally attach a screenshot of the final output, such as a downloaded PDF or Word document, a saved photo, or an attachment received in Teams. Choose a JPEG, PNG, or WebP image up to 8 MB. Annotated screenshots are supported. The button and selection message use the app language. The system file picker uses your browser or device language. Preview the selected image before sending. This image is stored separately from the automatic app screenshot; it does not replace it.',['Result screenshot','App issue']);
add('issueResultRemove','Remove the optional result screenshot from this unsent report. The automatic app screenshot and your description remain. Choose another image to replace it. Closing the dialog clears unsent evidence.',['Result screenshot','Draft']);
add('data-issue-app-evidence','View the screenshot captured from the Photo Notes page when this report was submitted. Compare it with the separately attached Result Screenshot when the problem appears only after saving, exporting, or sharing.',['App issue','Result screenshot']);
add('data-issue-result-evidence','Open the separately attached screenshot of the final result. Compare it with the original app screenshot and report description to identify where the output differs. A result screenshot is evidence, not a passing test result.',['Result screenshot','App issue']);
add('issueSend','Submit the app issue with its description and screenshot evidence, including the optional Result Screenshot. Review the screenshot and markup first. Wait for the displayed receipt/status and use My Issue Reports to track follow-up.',['App issue','Receipt']);
add('myIssueFilter','Speech clarification and failed retest replies can include recent speech event timing, recognized browser error codes, and release details, without recorded audio or note text. An approved improvement stays authorized when a retest fails. If you cannot test, explain what prevented it; your reply returns the already-approved work to repair. Ideas without owner approval remain in Ideas. Show open, closed, or all your issue reports. Read the repair/retest status for each report before deciding whether it still needs action.',['App issue','Status']);
add('issueDetailsResult-*','Choose Providing more information to answer the clarification request, or I retested and it is now working after checking the reported behavior. A confirmed-working reply closes the issue and records your result and written test evidence; it does not invent a deployed fix.',['App issue','Retest']);
add('data-pair-complete','This document contains only one member of a saved Before/After pair. Add Missing Before Photo or Add Missing After Photo adds its paired photograph to this document after your click. Regenerate the PDF or Word export to include the complete pair. Existing downloads and sent snapshots do not update automatically.',['Before/after','Document']);
add('issueDetails-*','Supply the additional reproduction details requested for this report. Answer the specific question, describe your device/browser, and distinguish what you observed from what you suspect.',['App issue']);
add('retestNotes-*','Record the steps you repeated, what happened, and any reason you could not retest. Only mark the retest successful after verifying the requested behavior on your device. Failed or unavailable retests require a written description of the steps, actual result, or what prevented testing.',['Retest']);
add('issueMarkupUndo','Undo the latest screenshot annotation. Review the remaining marks before submitting the issue. This does not alter your saved photo evidence.',['Markup','App issue']);
add('issueMarkupClear','Clear all annotations on the issue screenshot. Keep only marks that identify the problem before sending.',['Markup','App issue']);
add('issueMarkupRetake','Capture a replacement screenshot of the current app state. Check it shows the problem and does not include information you do not want to submit.',['App issue']);
add('issueMarkupColor|issueMarkupText','Choose screenshot-markup color or enter a text label, then place the label on the screenshot. Use arrows/marks to identify the app problem without covering relevant details.',['Markup','App issue']);
add('profileButton','Open your account menu to switch versions, access your testing/issue records, inspect pending uploads, install the app, or sign out. Available options depend on your account permissions.',['Account access']);
add('editionSwitcher','Choose one of the versions enabled for your account. Save the current draft first. Switching versions opens Capture in the chosen edition, even if you arrived through an Issue Updates link. Road Issue Reporter opens its report capture screen. Changing version changes available workflows and does not change your account identity.',['Edition','Draft']);
add('signout','Sign out of this device’s session. Save your draft and finish pending uploads first. Pending files may remain in this browser; return with the same account and original version to upload them.',['Local save','Account access']);
add('pendingPhotos','The centered pending PhotoNotes popup opens automatically when upload fails and explains the reason. Review PhotoNotes saved on this device that have not uploaded yet. Connection failures retry every 10 seconds. Stop or continue retrying, or show saved PhotoNotes in Library on this device. A local save is not a confirmed upload.',['Local save','Upload']);
add('installHelp|installAppButton|installGuideDone|closeInstallHelp|installDevice','Open or follow the installation guidance for this device. The installed app name is PhotoNotes AI. Existing saved shortcuts may retain their original name. Add an app icon using the browser/operating-system steps shown. Installation uses the same account and versions; it does not make every tool work offline.',['Installation']);
add('installNotNow','Dismiss the installation prompt and continue in the browser. You can open installation guidance later from the account menu or footer.',['Installation']);
add('testingAllIssues|testingReturn|testingAssignments|testingIssues','Use My Testing Dashboard for your own assignments and issue reports. Testing Administration manages published assignments and results. Issues & Retests opens all issue records for Super Admins and testing managers. Back to Photo Notes returns to the photo screen you left.',['Testing assignment','Retest']);
add('myAssignment|manageTesting|testingManagementBack','Open your assigned testing instructions or the testing-management workspace when authorized. Work through each step, attach failures to app issue reports, and record actual results before submitting.',['Testing assignment','Retest']);
add('email|pw|loginBtn','Sign in with the email and password for your PhotoNotes account. Check the email spelling. Login problems appear below Sign In in large, bold red text and are announced to screen readers. Read the message and use Retry Connection when offered. If credentials fail, contact your administrator rather than creating a second account to access the same records.',['Account access']);
add('tabCapture|tabOrganize|tabEdit|tabCreate|tabSend','Use the centered main navigation row to open Capture, Library, Create, or Send. Library combines finding, organizing, and editing saved PhotoNotes. Open a PhotoNote to edit its photo, note, details, comments, markers, and other available tools. Property Manager and HOA retain their separate specialist workspaces.',['Capture','Library','Document','Workflow menu']);
add('cname|edit-name-*','Enter the person’s first and last name for their account. Check identity before editing an existing user.',['Account access']);
add('cemail|edit-email-*','Enter the user’s sign-in email. Verify it belongs to the intended person, especially before changing an existing account.',['Account access']);
add('cindustry|edit-industry-*','Describe the account’s industry when useful. This descriptive field is separate from its version access and paid-plan permissions.',['Edition']);
add('cpass|reset-password-*','Set a new password for this account. Use a strong password and deliver it through an appropriate private channel. Resetting a password does not send it automatically.',['Account access']);
add('generatepass|copypass','Generate or copy a recommended password for the account being created. Check which user the password is for before saving or sharing it.',['Account access']);
add('createbtn|addUser','Open account creation or create the entered user. Confirm first/last name, email, password, versions, testing access, and features before saving.',['Account access','Edition']);
add('userSearch|sortsel','Search the account list by name/email or change its sort order. This affects the list view, not account permissions.',['Filter']);
add('issueVersionFilter|issueTypeFilter|issueStatusFilter|issuePriorityFilter|issueDateSort|issueRecommendedAction|issueTesterFilter|issueDeviceFilter','Filter or sort app issue reports by the field named here. Combine filters to find the desired reports, and broaden them if an expected issue is missing. The filter does not update the report’s saved status or priority.',['Filter','App issue']);
add('ui-decision-*|ui-instructions-*','Choose the review decision and enter specific instructions for this app issue. Explain the evidence and next action. Submitting a decision updates the review workflow; verify the resulting status.',['App issue','Retest']);
add('refreshAssignments','Refresh testing-assignment progress and submissions. Compare recorded steps, defects, and the tester’s summary before marking an assignment reviewed.',['Testing assignment']);
add('stripeCustomerName|stripeCustomerEmail','Enter the customer/company and billing email for this invoice. Verify the billing recipient before creating a draft.',['Invoice']);
add('stripeDba','Select the business identity issuing the invoice. Confirm the intended provider before billing.',['Invoice']);
add('stripeDue','Choose the invoice payment due period. Check the resulting due date in the draft before finalizing or sending it.',['Invoice']);
add('stripeDescription','Describe the billed service or product clearly enough for the customer to identify it.',['Invoice']);
add('stripeAmount','Enter the invoice amount using the currency/units shown. Review the total before creating the draft.',['Invoice']);
add('stripeCreateInvoice','Create a Stripe draft invoice using the reviewed customer, business, description, amount, and due period. A draft is separate from a finalized/sent invoice or a completed payment.',['Invoice']);
add('delete-email-*|confirmDeleteUser','Review the permanent account-deletion scope and type the required email confirmation. This can remove associated records; cancel if the identity or scope is uncertain.',['Account access']);
add('retryUsers','Retry loading the account list after checking the connection. This does not recreate users or alter their permissions.',['Account access']);
add('footer-install|button','Open the full installation guide or return to the app as indicated by this link. Read the device-specific instructions and confirm saved uploads before changing browsers.',['Installation']);
add('alignCam|alignment-choice','Choose the Before source photo or capture the matching After image. Review the date, location, landmarks, and camera angle. An alignment guide helps compare the pair but does not certify that the viewpoints are identical.',['Before/after']);
add('photo-title-input','Enter a short descriptive photo title, then save it. Identify the subject, condition, and site so it can be found in the library and reports.',['Photo note']);
add('user-list-item|data-open-user','Open this account’s details. Confirm its name and email before changing versions, feature/testing access, active status, password, or deletion scope.',['Account access']);
add('data-active','Activate or deactivate the identified account. Deactivation blocks active use but is different from permanently deleting its records. Review identity before confirming.',['Account access']);
add('data-retry','Retry this saved Ramo submission. Reuse the existing submission and attachments instead of creating a duplicate. Verify received status and the receipt afterward.',['Ramo','Receipt']);
add('ramoBack|shortcutClose|data-back','Return to the previous workspace or close the current panel. Save unfinished work first when needed. Closing does not confirm delivery.',['Draft']);
add('data-issues|data-report','Open issue history or report a defect linked to the current test step. Include the step, actual behavior, expected result, and source screenshot.',['App issue','Testing assignment']);
add('data-device','Record the device, operating system, browser, and interface language used for this test. This helps distinguish platform-specific failures and reproduce the result.',['Testing assignment']);
add('data-result','Record this step as passed, failed, blocked, or not tested, using the offered choices. Only mark Passed after observing the expected behavior; a completed checkbox alone is not proof of success.',['Testing assignment','Retest']);
add('data-notes','Describe the actual test result and related issue report numbers. Include the failure steps or reason the step was blocked/not tested.',['Testing assignment','App issue']);
add('data-photo','Attach photo/screenshot evidence to the current test step. Observe the stated size and count limits and check that the image supports the recorded result.',['Testing assignment','Evidence']);
add('data-overall','Summarize the testing session, remaining failures, blockers, and untested steps. Do not describe an untested feature as working.',['Testing assignment']);
add('data-save','Save the testing results entered so far. Review the displayed save status. Saving progress is separate from submitting the assignment for manager review.',['Testing assignment','Draft']);
add('data-submit','Submit the testing results and evidence for review. Failures and untested steps may be submitted with explanations. Submitted is not the same as Passed.',['Testing assignment','Status']);
add('data-new|data-edit|data-add-step|data-remove-step|data-save-draft|data-publish|data-preview','Create or edit the testing assignment, add/remove steps, save a draft, preview, or publish as labeled. Review ordered instructions and expected results before publishing to the selected testers.',['Testing assignment','Draft']);
add('data-field|data-user','Edit the testing template field named by its label or choose the intended tester. Supply accurate English/Spanish instructions and observable expected results. Preview the complete assignment before publishing.',['Testing assignment']);
add('submitter_name|customer_name','Enter your name so the property submission or customer review records who provided this response. Check the photographs and instructions before submitting.',['Evidence','Approval']);
add('photos','Choose the required completion photos showing the finished work. Include clear overview and detail images, then describe what was done before submitting to the property manager.',['Completion link','Verification']);
add('comment','Explain your customer review response. Identify any change requested and the relevant photo. Submit only after inspecting the package.',['Approval']);
add('data-area','Choose this saved topic for the current capture, or choose No Topic to leave it untagged. Add a new topic using the topic-name field when none fits.',['Topic']);
add('data-camera-tool','Open this specialist photo tool. Read its description, photograph the source clearly, review the extracted or measured fields, and save only confirmed details. Tool availability depends on the selected edition and account features.',['Camera reader','Evidence']);
add('data-visit','Continue this guided property visit or review its completed photos. Work through route stops in order, inspect the required views, and record actual findings.',['Property visit','Inspection route']);
add('data-issue-tool','Choose the screenshot annotation tool: select/move, arrow, rectangle, circle, line, or text. Drag on the screenshot to mark the relevant app problem, then review the screenshot before submitting.',['Markup','App issue']);
add('data-version-owner','Enable or disable this edition for the selected user. Check that the version and account match the intended access before saving. This changes access, not the photo records.',['Edition','Account access']);
add('testing-download','Download the current published assignment as a PDF. Use the live Testing Dashboard form to record results and evidence for each step; the PDF alone does not submit results.',['Testing assignment','PDF']);
add('data-add','Add Individual Marking adds one marking at a time. Templates apply a reusable group of markings. Add the named annotation to the photo: date/time, address, GPS, copyright, topic, custom text, box, arrow, or the offered specialist details. Drag it to the relevant evidence, adjust its appearance, and save changes. Address and GPS use the selected photo’s actual saved values; missing metadata produces no marking. Copyright presets use the complete Zukor AI copyright notice.',['Markup','GPS']);
add('data-col','Choose this preset annotation color. Use contrast against the photograph and avoid hiding important evidence. Save Changes to retain the completed markup.',['Markup']);
add('data-pos|data-dir','Position the selected label at the indicated corner or set the arrow direction. Check the target evidence, then save the completed markup.',['Markup']);
add('stampStage','Add an annotation above/below this canvas, drag it into position, and drag the corner handle to resize a box or arrow. Select an item to change its appearance. Save Changes retains the editable markings; Download Marked Photo creates a separate flattened image.',['Markup','Original']);
add('cropStage','Drag the crop region and its handles to frame the relevant evidence. Review all edges before Apply Crop. Cancel leaves the saved photo unchanged, and Restore Original can recover the first uploaded image.',['Crop','Original']);
add('photo-viewer-button','Open the full photo viewer. Zoom and pan to inspect visible details, then reset the view or close it. These viewing adjustments do not edit the original.',['Original']);
add('data-step-field','Write the ordered test step’s title/instructions in the language labeled here. Describe a specific action and observable expected result, then save the assignment draft and preview it before publishing.',['Testing assignment']);
add('data-assignee','Choose this tester to receive their own copy of the published assignment. Verify account identity and intended edition access before publishing.',['Testing assignment','Account access']);
add('data-person|data-status','Filter testing runs by the person or recorded workflow status. This changes the results shown, not the assignment’s saved outcomes.',['Testing assignment','Filter']);
add('keyboardDictation','Use the microphone on your phone keyboard to enter notes if browser recording is unavailable. Tap the notes field, open the keyboard microphone, speak, review the words, and save the capture.',['Capture']);
add('shareOriginalPhotos','Share the selected original photo files using the available device sharing or download action. Review the recipients and attachments. Original photos do not include the composed document layout or every saved annotation.',['Selection','Document']);
add('firstUseYes','First-time setup asks for microphone, camera, then location access in that order, followed by Home Screen installation on eligible phones. Enable the permission requested in this setup step, or follow the Home Screen installation instructions. Location lets Photo Notes attach where a photo was taken; setup does not save your location or start continuous tracking. Browser permission may be requested. Successful permission requests advance automatically to the next setup step. If access fails, retry or continue. Permissions can also be changed later in browser settings.',['Installation']);
add('firstUseNext','Skip the current setup request, continue after an unsuccessful permission request, or close the Home Screen installation instructions with Done. Not Now leaves that permission or installation step incomplete. You can enable it later when using the relevant feature.',['Installation']);
add('ewrReason','Choose the cause of the extra work shown by these photos. Select the closest listed reason and describe the specific condition and scope in the notes. A reason identifies the request and does not constitute customer approval.',['Evidence','Approval']);
add('ewrNmethod','Record how the customer or responsible person was notified about the extra work. Select the actual communication method and retain the relevant date and details. Notification is separate from approval.',['Approval']);
add('data-issue-recommend','Prepare the recommended action for this issue. Review the suggested investigation, repair, clarification, retest, or closure instructions, edit them if needed, then submit the decision. Preparing a recommendation alone does not queue or send it.',['App issue','Retest']);
add('audio|video','Play or pause the attached recording using its media controls. Adjust volume and seek through the recording where available. Listen to the complete description before acting on the associated photo or issue. Playback does not save, submit, approve, or change the record.',['Evidence']);
add('data-ref','Choose the reference object whose known size you will use to calibrate the photograph. Place the reference in the same plane as the measured area and confirm its real size. Perspective and visibility affect the resulting estimate.',['Measurement']);
add('testingAllIssues','Open the complete Issue Management Center to monitor all testers, open reports, closed reports, retest instructions, replies and investigation history. Testing managers have monitoring access; owner decisions and repair changes remain with the Super Admin. Outstanding retests receive in-app reminders every four hours for the tester and active testing managers until a result is submitted. Enabled browser notifications receive them too. Email copies require a configured email service. New retest and clarification requests send an initial email immediately to the reporter and active testing managers; additional retest emails follow the schedule saved by the Super Admin in Email Notification Settings and can be switched off. In-app reminders stay every four hours.',['App issue','Retest']);
add('issueArchiveLink','Switch between Open Issues and Closed Issues. This separate link has no count. Closed Issues shows only closed reports, with total and closure-category counts. Other filters remain active.',['App issue','Retest']);
add('data-issue-queue','Open Issues counts all reports that are still open and appears first. In Closed Issues, All Closed Issues counts the entire closed view; the other buttons divide it into verified fixes, closures without a fix, and closures without verified repair evidence. Counts respect the other active filters. The list heading states how many issues are open or closed in the selected view, including the chosen tester. Open the issue queue named by this button. Needs Sam\'s Review requires owner review, Waiting for Tester requires a tester response, Ideas holds suggestions, Developer Investigation holds technical failures requiring developer review. Awaiting Developer Repair includes new bugs and approved work queued for investigation, repair or verification. It does not mean a developer is currently working on every report. These five categories divide all Open Issues without overlap, so their counts add up to the Open Issues total. Completed, Fixed and Verified requires a recorded fix, commit, deployment, verification and successful reporting-tester retest. Closed Without Verified Fix holds other closed reports. Review the next action and responsible person shown on each report.',['App issue','Retest']);
add('data-feature-key','Enable or disable the named feature for this account. Camera Readers & Scanners applies across all seven enabled Pro editions. Ticket scanner, Before/After matching, measurements/map/classification, and Extra Work Records settings apply only to Paving Pro. Review the selected account, then use Save Feature Access. Disabling a tool changes availability; it does not delete existing photo evidence.',['Account access','Edition']);
add('data-testing-manager','Give this user access to create and publish testing assignments, review tester results, and request retests. This does not grant account administration. Review the account and use Save Testing Access to retain the setting.',['Testing assignment','Account access']);
add('data-close','Close this panel or editor. Review unfinished work and use its Save or Submit action before closing if you want to retain changes. Closing a sharing panel does not deliver a file, and closing an assignment editor does not publish it.',['Draft']);
add('data-share','Open the device sharing choices for the prepared photo or file. Check the destination, recipients, and attachments, then complete the sharing action. Closing or canceling the sheet does not deliver anything. Keep the local capture until its upload status is confirmed.',['Share sheet','Local save']);
add('svSelect|svManage','Choose a personal Saved View to restore this workspace’s existing filters and show current authorized results. Manage View opens its name, description and saved criteria. Saved Views are separate for each edition and workspace. Missing criteria pause results until you update the view or clear it.',['Saved View']);
add('svSave|svName|svDescription|svSubmit','Save the current search text, supported filters and exact date ranges with a required View Name and optional Description. This saves criteria on your account when connected, without copying photos or creating a folder, Photo Set, job, document or report. New matching photos appear automatically.',['Saved View']);
add('svDefault','Apply this Saved View automatically when this edition’s relevant workspace opens. Only one view can be Default per workspace. Uncheck Default and Save View to stop automatic application. All Photos or All Records clears it for the current visit.',['Default View','Saved View']);
add('svReplace','Replace the stored criteria with the filters currently shown in the workspace. Leave unchecked to change only name, description or Default. Unavailable criteria are removed only after explicit confirmation.',['Saved View']);
add('svAll','Clear all filters and the active Saved View for this workspace. All Photos returns to your authorized library. All Records restores the maintenance workspace’s normal open-record defaults. This does not delete or change a saved Default.',['Saved View']);
add('svDuplicate|svDelete|svCancel','Duplicate creates an independent copy of the criteria with an editable name and no Default. Delete removes only this Saved View after confirmation, never photographs. Cancel closes without saving. Failed saves keep the dialog open.',['Saved View']);
add('ctOptions|ctUse|ctManage|ctChoice|ctApply|ctLast','Saved Capture Settings are grouped with Topic, Urgency, and Additional Details below the photo and notes controls. These optional choices are not required before taking a photo. Open Saved Capture Settings to use the three compact actions: Use Saved Settings, Save Current Settings, and Manage Saved Settings. Choose a named set of settings owned by your account for this edition. Use Saved Settings and Last Used Settings apply only configured defaults. Nothing applies automatically. Review and change every selection before saving the photograph. Unavailable choices are skipped. Saved Capture Settings are separate from Annotation Templates and Photo Set templates.',['Saved Capture Settings']);
add('ctSaveSetup|ctNew|ctEdit|ctDuplicate|ctName|ctDescription|ctTopic|ctUrgency|ct-concretePhase|ct-concretePurpose|ct-concreteElement|ct-hoaType|ct-hoaPriority|ct-hoaArea|ct-pavingPhotoReason|ctSave','Create, edit, rename or duplicate reusable defaults. Settings Name is required; description and selections are optional. Leave unchanged does not overwrite the current capture value. Save Current Settings copies only safe current selections. No photo, narrative, GPS, address, time, job, property, condition or severity is copied. Save Settings stores on this device and syncs to your account when connected. Cached saved settings remain usable during an already available offline Capture session.',['Saved Capture Settings','Local save']);
add('ctDelete|ctClose','Delete the selected set of Saved Capture Settings, or close settings management. Deleting saved settings never changes saved Photo Notes. Deletion syncs when connected. Saved settings belong to your account and edition; there is no team sharing.',['Saved Capture Settings']);
add('duplicate-photo-note|duplicateStart|duplicateCancel|duplicatePhotoDialog','In Organize, Edit or Photo Library, Duplicate for New Photo starts a separate Capture using safe organizational context from this saved Photo Note. Review the Topic, Job or Property and specialty context, take or choose a new photograph, add new details, and save normally. Cancel leaves the source unchanged. No photo, location, analysis, measurements, approvals, status, history or relationships are copied. Save on this device can remain pending until upload is confirmed.',['Context reuse','Evidence','Local save']);
add('duplicateCopyNotes','Copy Notes is off by default. Select it deliberately to copy the original note text, then remove or correct any facts that describe the previous photograph before saving.',['Context reuse']);
add('duplicateJob|duplicateCaptureContext','Review and change the copied Job / project before saving. No job address or photo location is copied. Capture acquires location normally for the new photograph. Only the first Topic is preselected, and it can be changed using the normal Topic controls. Concrete retains phase, purpose and project type. Property and HOA retain available community, category and record type; Property retains an available named Area.',['Context reuse','Evidence']);
const terms={
 'Contact file':'A vCard (.vcf) file containing saved contact details that a compatible address book can import. It does not add a contact automatically.',
'Annotation template':'A private named set of editable photo markings reusable on one or many photos. Custom text is reused literally; photo-field labels resolve from each destination photo. Saved Capture Settings are separate.',
'Result screenshot':'An image of the final output after saving, exporting, downloading, or sharing. It is separate from the automatic screenshot of the Photo Notes page.',
'Exact Location':'Specific human-readable details within an Area, such as third light pole from the entrance.',
'Workflow menu':'The row of section tabs that remains at the top while scrolling in editions with a workflow menu. Only available sections are shown.',
'Library':'The shared workspace for finding, organizing, opening, and editing saved PhotoNotes. Library and section headings use black text on white panels in either appearance mode.',
'Group':'A named collection inside one project. A PhotoNote can belong to more than one group and more than one project.',
'Inactive Area':'An Area retained for historical references but unavailable for new assignments.',
 'Damage / Incident':'One Property Manager photographic record of observed physical conditions, with context and multiple linked Photo Notes. It does not establish cause, liability, coverage or legal responsibility.',
 'Observed time':'The entered time the user observed or documented the condition, distinct from the underlying incident time.',
 'Reported incident time':'Optional user-entered incident date and time, not independently established by a photograph.',
 'Incident view':'The photographic purpose used to group incident photos. Irrelevant views can be skipped with a reason.',
 'Incident status':'Open, Documented or Closed, used only to organize photographic records.',
'Property Area':'A reusable named location within one Property, such as North Parking Lot. It is separate from a maintenance category, exact location description, and GPS.',
 'Web push':'Optional device notifications delivered by the browser or installed app after permission and explicit subscription.',
 'Photo follow-up':'A saved requirement to photograph the same subject again on a future date.',
 'Scheduled photo':'A saved requirement to take another photo of a subject or project on a due date for a stated reason.',
 'Photo history':'The dated record connecting a scheduled photo with its subject, reminders, and resulting PhotoNote.',
 'Occurrence':'One dated photographic requirement within a one-time or recurring schedule. Missed occurrences stay in history.',
 'Monitoring history':'The reference photograph and later photographic observations connected to a stable subject, with dates and occurrence outcomes.',
 'Reference photograph':'An earlier saved photo shown to explain what and where to photograph. Its evidence metadata is not copied.',
 'Recurrence':'A calendar interval that generates separate dated photographic occurrences.',
 'Time zone':'The named local zone used to decide when a date-only photograph becomes due.',
 'Saved View':'A personal, edition and workspace specific saved search and filter configuration. Its results are dynamic and limited to records you can already access. It contains no photo copies or static photo selection.',
 'Default View':'The optional Saved View applied when its Organize or maintenance workspace opens. Use All Photos or All Records to clear it during your current visit.',

 'Request status':'Open means no received views; Partially Submitted means some received; Completed means all received; Expired or Cancelled closes submission.',
 'Private link':'A difficult-to-guess bearer link restricted to one photo request; possession allows submission until closure or expiration.',
 'Requested view':'A named photographic viewpoint or detail; each requested view requires one received photo.',
 'Photo Request':'A request for specific photographic information returned to the requesting Photo Notes user.',
'Visual analysis':'AI interpretation of visible photographic evidence using a domain-specific vocabulary. It cannot establish hidden conditions, cause, engineering adequacy or safety.',
'AI Suggested':'An AI result awaiting human review. Suggested values do not automatically replace photo fields or enter customer reports.',
'User Reviewed':'A result explicitly accepted or corrected by the user. Review records retain the original AI result and do not constitute engineering certification.',
'Analysis confidence':'High, medium or low confidence in the AI interpretation of visible evidence, overall and per finding. This is not engineering certainty.',
'Capture Location':'Original device GPS obtained when the photo was taken or selected, preserved independently of subject corrections.',
'Subject Location':'The physical object or condition shown in the photo, which may be away from the photographer.',
'Location Description':'Optional landmarks describing exactly where to find the subject, separate from the postal address.',
'Camera Direction':'Reliable recorded camera-facing compass direction. The uploaded photo must contain explicit EXIF image direction with a true- or magnetic-north reference. Device travel heading is not camera direction.',
 'Custom Field':'Simple user-entered metadata belonging to one Photo Note. It supplements notes and specialty fields and is not verified photographic evidence.',
 'Field scope':'General applies within your Pro account across supported editions. Edition applies only in the selected Pro edition. Job and Property scopes are not yet supported.',
 'Field revision':'A retained version of a field definition. Saved and queued values keep their labels and choices after a rename, option change or deactivation.',

 'Favorite':'A persistent internal star marker for easy access over time, until you remove it. Separate from topics and urgency.',
 'Flagged':'A persistent internal attention marker, until you remove it. Creates no task, reminder, due date, priority or assignment.',
 'Export Preset':'A named, user-owned set of packaging defaults. It does not contain photographs or a delivery destination.',
 'Image Quality':'The maximum image edge and compression used for output, without enlarging smaller originals. Standard: 2048 pixels; Print: 3000; Web: 1400.',
 'Related Photos':'An explicit, bidirectional link between independently saved photographs. It preserves context without creating a Photo Set, Before/After pair or organizational record.',
 'Relationship type':'An optional user description of why two photos are linked. Cause and effect labels record the user description, not an automated conclusion.',
 'Saved Capture Settings':'A named set of reusable capture choices, such as Topic and Urgency. Apply it to a new Photo Note, take a new photo and add new notes. It does not reuse photographs, recorded notes or location.',
'Before/after':'Two linked photographs showing an earlier condition and a later condition. Compare matching viewpoints and confirm their dates before drawing conclusions.',
 'Capture':'A photograph and its supporting note, location, and other details recorded in PhotoNotes.',
 'Photo note':'The words attached to a photo explaining what it shows and why it matters.',
 'Draft':'Work still being edited on this device that has not yet been saved or submitted.',
 'Original':'The first uploaded image, retained separately from later visual edits where supported.',
 'Evidence':'The source photo and supporting record used to document a condition, event, or work.',
 'Topic':'A user-created subject label that groups related photos. A photo can be untagged.',
 'Category':'A named type of property issue or work used to classify and find records.',
 'Job':'A named work/site record grouping photos for the same customer or piece of work.',
 'Project':'The job or site context associated with photos and supporting records.',
 'Community':'The managed property/community associated with its assets, visits, and maintenance records.',
 'Asset':'A specific physical object maintained by a property, tracked through identity and condition photos.',
 'Property visit':'A recorded inspection walk containing ordered stops, required photos, and findings.',
 'Inspection route':'A reusable ordered list of inspection stops and the photo views expected at each stop.',
 'Maintenance record':'A property issue or request with photos, description, responsibility, and progress.',
 'GPS':'Latitude and longitude obtained from location services or usable photo metadata. Accuracy varies.',
 'Geocoding':'Translating coordinates into an address or readable geographic description. Map data may omit local site names; review the result and correct the address when needed.',
 'Permission':'Browser or operating-system authorization for access such as camera, microphone, or location.',
 'Dictation':'Speech converted to editable written text. Review the words before saving.',
 'Local save':'A draft/capture stored in this browser on this device while awaiting server upload.',
 'Upload':'Sending the photo/record to the PhotoNotes server. It is separate from a local save.',
 'Photo Library':'Your saved Photo Notes. In Send, open Select Photos to browse the library and choose records for the next delivery action.',
 'Selection':'The Photo Notes chosen for an action. In Send, changing filters keeps this set, including hidden records. Check the total and outside-filter counts before delivery.',
 'Filter':'A view restriction that narrows displayed results without deleting records.',
 'Document link':'A seven-day download link to a saved document snapshot. Anyone with the link can download it until it expires or its owner revokes it.',
 'Document':'A named, ordered report made from photo copies, captions, and supporting details. A nonblank title is required when creating or renaming it. Start with the Library selection or review photos from a project or topic in Create.',
 'Caption':'Text explaining an individual photo in a report or grouped submission.',
 'PDF':'A document format preserving the finished page layout for viewing and printing.',
 'Word':'An editable .docx document that can be opened in Word or compatible software.',
 'Markdown':'Plain text with simple formatting. Markdown + Photos exports text and images in a ZIP package.',
 'Resolution':'The number of pixels in an image. Lower-resolution exports can lose visible detail.',
 'Download':'Saving a generated file to this device. It does not automatically send the file to anyone.',
 'Share sheet':'The operating system or browser’s destination chooser used to share a prepared file or review link.',
 'Shortcut':'A saved delivery destination associated with your account for reuse.',
 'HTTPS':'A secure website URL starting with https://. It protects the connection, not the accuracy of content.',
 'Approval':'A recorded customer/board decision. Creating or sharing a review link is not approval.',
 'Completion link':'A private link used to submit photos of completed property work for later verification.',
 'Receipt':'A saved confirmation from the receiving workflow. Check its status and attachment count.',
 'Ramo':'The authorized Ramo Optimizer integration receiving grouped photo evidence submissions.',
 'Checkout':'The hosted payment review flow. Opening it does not complete a payment.',
 'Invoice':'A billing document. Draft, finalized, sent, and paid are different states.',
 'Markup':'Arrows, shapes, text, or other annotations placed on a photo or screenshot.',
 'Crop':'Reducing the visible image frame to a chosen region. The original may be restored where supported.',
 'Template':'Reusable annotation or document structure. A Word template needs the supported placeholders.',
 'Branding':'Company name, logo, and header/footer elements used in a report.',
 'AI':'Automated image/text analysis. Its output must be checked against the source evidence.',
 'Camera reader':'A tool extracting visible values from a source photograph for review and saving.',
 'Condition':'The observed state of the photographed object, distinguished from scheduling priority.',
 'Defect':'A visible fault/classification suggested by AI or entered after human review.',
 'Severity':'How serious the observed issue is. It is separate from response urgency.',
 'Internal Discussion':'Private text discussion attached to a saved photograph, visible only through existing photo access.',
 'Mention':'An @Name reference to an authorized team member. HOA and Property use existing in-app notifications.',
 'Comment History':'Retained previous comment text and deletion metadata. Deleted text is hidden from the discussion.',
 'Urgency':'Standard or Urgent handling recorded with a capture. It is not a notification guarantee.',
 'Priority':'The property workflow’s follow-up importance, such as Routine, High, Emergency, or Monitor.',
 'Proposal exhibit':'A photo document attached to a proposal to illustrate the proposed work or existing conditions.',
 'Project phase':'The stage of work documented by a concrete photo, from proposal to follow-up.',
 'Photo purpose':'The reason the photograph is being captured within the selected workflow or phase.',
 'Specification':'A confirmed requirement or mix/material detail from a reliable source, not a visual guess.',
 'Area':'The two-dimensional size of a traced shape or measured surface, with stated units and source.',
 'Measurement':'A reviewed dimension or area. Assisted/photo/map estimates are not certified surveys.',
 'Reference':'A known real-world size visible in the image used to estimate another dimension.',
 'Provenance':'Information about where a record or measurement came from and how it was obtained.',
 'Fingerprint':'A digital hash identifying file bytes. Matching hashes do not prove an event’s truth.',
 'Verification':'A documented review of supporting evidence and results, separate from an automatic suggestion.',
 'Timeline':'An ordered history of photographs, work stages, and recorded changes.',
 'Status':'The recorded stage of a workflow. Read its meaning rather than assuming a click completed the task.',
 'Target date':'The planned completion date, distinguished from actual completion.',
 'Budget':'The source and estimated/actual cost of funds associated with property work.',
 'Assignment':'The person responsible for a record or the person asked to answer a request.',
 'Extra work':'Additional work documented with its cause, scope, notification details, and photo evidence.',
 'Notification':'An app/browser alert. Reading an alert does not resolve the underlying work or issue.',
 'Road issue':'A photographed road problem submitted through Road Issue Reporter, separate from app defects.',
 'App issue':'A software problem or suggestion concerning PhotoNotes, sent through Report Issue.',
 'Email notification':'An immediate email for a new issue report, retest request, or request for more information or clarification. The Super Admin can enable or disable these emails independently of recurring retest reminders.',
 'Email reminder':'An additional email requesting a pending retest. The Super Admin chooses whether it repeats and how often, independently of immediate issue notification emails.',
 'Retest':'Repeating specified steps after a repair and recording whether the behavior actually works.',
 'Testing assignment':'A set of instructed checks and results for a tester, with review/submission status.',
 'Account access':'The versions, tools, and roles assigned to a signed-in account.',
 'Edition':'One enabled version of PhotoNotes, such as Basic, Pro, or an industry edition.',
 'Installation':'Adding an app icon through a supported browser. This does not provide offline support for every feature.'
};
Object.assign(terms,{'Document Settings Preset':'A named reusable set of document layout and style choices. It does not set the document title or choose photos.','Default':'The settings automatically shown when starting a new document. They remain editable for each document.','Last Modified':'The date a document title, description, settings, photo membership, caption, or order was most recently saved.'});
terms['Context reuse']='One-time reuse of safe organizational fields from an earlier Photo Note. The new photograph has its own record and evidence trail; this creates no photo relationship or saved template.';
add('paProperty|paName|paDescription|paCreate|paEditName|paEditDescription|paEditActive|paSave|data-property-area','Choose a Property, enter a required Area Name and optional Description, then Create Area. Edit an existing Area and Save Area to change its name, description or Active status. Inactive Areas remain on historical records but cannot be selected for new assignments. Areas belong only to their Property and do not require GPS.',['Property Area','Inactive Area','Exact Location']);
add('paCaptureArea|paAssetArea|paRecordArea|paSaveAssociation|paStop|paStop*','Choose an optional named Area within the selected Property. No Area is valid even when Areas exist. Capture Save, Save Asset Photo Record and Create Photo Route save their Area choices with the record. On an existing record use Save Area separately from Save Maintenance Record. Exact Location describes a more precise position and remains separate from Area and geographic location.',['Property Area','Exact Location']);
add('paItemFilter|paAssetFilter|paInspectionFilter|paVisitFilter|paAssetSearch|paAssetSearchButton','Filter this collection by a Property Area, including inactive Areas retained by historical records. All Areas removes this filter. Area names also participate in maintenance, asset and photo text search.',['Property Area','Inactive Area']);
add('pavingPhotoReason','Choose why this paving photograph is being taken. The selection determines which supporting tools or details appear. Read the on-page description and choose the reason supported by the photo.',['Photo purpose']);
const textRules=[
 {match:'^Light mode$|^Dark mode$',text:'Choose the app appearance. Dark mode uses the transparent white-letter Zukor AI logo with a bright red colon and readable text on dark feature panels, including Saved Capture Settings, Saved Views, Photo Follow-Ups, Photo Requests, Create document settings and document lists, and Send document choices. Industry editions also use a transparent PhotoNotes header with a white wordmark in dark mode. Help and exported documents keep black text. Changing the theme does not alter photo records, notes, or exported document content.'},
 {match:'Open the printable PDF version',text:'Prepare the printable PDF of this document, review the print preview, and choose the desired printer/settings. This does not send the document to a customer.',terms:['PDF','Document']},
 {match:'^Tester$|^Status$|^Version$',text:'Filter testing assignments by the selected tester, workflow status, or PhotoNotes edition. These filters narrow the view and do not change assignment results or account access.',terms:['Testing assignment','Filter']},
 {match:'^View & Zoom$',text:'Open the full photo viewer to zoom and pan across visible evidence. Reset the view or close it when done; viewing controls do not edit the original.',terms:['Original']},
 {match:'Download Original Photo|Download Notes and Details',text:'Save a backup of this pending photo or its supporting note/details to this device. Verify the backup before clearing browser storage. A backup is separate from successful server upload.',terms:['Local save','Original','Upload']},
 {match:'Retry Current Version',text:'Retry pending uploads owned by the signed-in account in the current edition. Return to a capture’s original version if needed and wait for upload confirmation.',terms:['Local save','Upload']},
 {match:'Document download link|Copy link|Share link|Create.*link|Revoke',text:'Create, copy, share, or revoke the private document link as labeled. Check the file and expiration before sending it. Copying a link is not delivery; revoking it prevents later access through that link.',terms:['Document','Receipt']},
 {match:'^(L|D)$',text:'Choose the light or dark appearance for the app. This changes the interface theme, not photographs, saved notes, or document content.'},
 {match:'^(EN|ES)$',text:'Choose English or Spanish for available interface text. Your existing photo notes and user-entered titles are not translated by changing this preference.'},
 {match:'^([×✕]|Close|Cancel|Back|Not Now|Got It|‹|←)',text:'Close this panel, cancel the current operation, or return to the named workspace. Save edits first if they should be kept. Cancel does not submit or confirm a delivery.',terms:['Draft']},
 {match:'^Zoom (In|Out)$|^Move (Left|Right|Up|Down)$',text:'Adjust the viewer’s zoom or pan to inspect image details. These viewing controls do not modify the saved photograph.',terms:['Original']},
 {match:'^(Top L|Top R|Bot L|Bot R|↘|↙|↗|↖)$',text:'Position the selected annotation at the indicated corner or adjust its direction. Review that the annotation points to the intended evidence, then save the markup.',terms:['Markup']},
 {match:'^No Topic$',text:'Leave the current photo without a topic tag. You can still save it and add topics later.',terms:['Topic']},
 {match:'Photo quality.*format',text:'Choose the resolution and image format for generated files. These settings affect exported copies, not full-resolution originals stored by PhotoNotes. Review small visual details before choosing a reduced resolution.',terms:['Resolution','Original']},
 {match:'^Apply Template$|annotation|arrow|rectangle|ellipse|line|^Text$',text:'Add or adjust the selected annotation tool/template on the photograph. Select the item to edit its position, size, color, or text. Review placement and save changes.',terms:['Markup','Template']},
 {match:'^Edit Document$|^Open$',text:'Open the selected record for review and editing. Check its identity, source photos, and details before changing it. Save edited fields before returning to the list.',terms:['Evidence']},
 {match:'^Delete$|^Remove$|Delete Record',text:'Remove the indicated record or attachment after checking the confirmation. Removing a document/photo copy does not delete the library original; deleting a saved record has a different scope. Read the exact target before confirming.',terms:['Original','Document']},
 {match:'View / Edit Area',text:'Open this saved photo-linked area to inspect and revise its outline, dimensions, measurement method, and notes. Verify the source photo and site before saving changes.',terms:['Area','Measurement']},
 {match:'Start Property Visit',text:'Start a guided visit from this inspection route. Confirm the community, then complete its ordered stops with the requested evidence photos and findings.',terms:['Property visit','Inspection route']},
 {match:'Open Photo History',text:'Review this physical asset’s identity photo and condition history. Add dated documentation as damage, repair, and verification progress.',terms:['Asset','Timeline']},
 {match:'Open Maintenance Record',text:'Open this property issue to review details, responsibility, priority, status, costs, and its photo timeline. Verify completed-work photos before closing it.',terms:['Maintenance record','Verification']},
 {match:'Open in Photo Library',text:'After saving a reviewed reader record, explicitly create or open its linked Photo Library note with the source photograph and reviewed fields as notes. Scanning and saving a reader record do not automatically publish a Photo Note. The note belongs to the same user account and opens in the current edition.',terms:['Camera reader','Evidence']},
 {match:'^Open in Organize$',text:'Open this map photo in the library workspace to review its note and supporting details. Check the location before attaching it to a site report.',terms:['GPS']},
 {match:'^Print$|Print Current Report',text:'Prepare the selected document/report for printing and review the browser’s print preview. Confirm page layout, paper size, and photo detail before printing.',terms:['PDF','Document']},
 {match:'^(Share|Download|Download PDF|Download Word)$',text:'Prepare the indicated file, then share it through an available destination or download it to this device as labeled. Open the resulting file to check content and layout. Downloading alone does not deliver it to another person.',terms:['Share sheet','Download','PDF','Word']},
 {match:'Download Starter Template',text:'Download the supported Word template starter. Preserve {{PHOTO_NOTES_CONTENT}} and any needed title/description/company placeholders, edit the design in Word, then import and preview it.',terms:['Template','Word']},
 {match:'^Save User$|^Edit$|^Save Feature Access$|^Save Testing Access$|^Save Versions$',text:'Save the named account setting for the selected user. Verify identity, assigned versions, feature permissions, and testing role. Account-level access determines which screens and tools that user can open.',terms:['Account access','Edition']},
 {match:'Reset Password|Recommend Password|Copy Password|Save Password',text:'Set or copy a strong replacement password for the selected user. Verify the account and save the change. Communicate the password privately; copying it does not notify the user.',terms:['Account access']},
 {match:'Delete User|Delete Permanently',text:'Review the account-deletion scope and required email confirmation before proceeding. Permanent deletion can remove associated evidence and records. Cancel if the user identity or scope is uncertain.',terms:['Account access','Evidence']},
 {match:'Activate|Deactivate',text:'Change whether the selected account is active. Review the user identity and access consequences before confirming. Deactivation differs from permanent deletion.',terms:['Account access']},
 {match:'Admin Dashboard|Super Admin Dashboard|^Open App$|Back to the app',text:'Open the named administration workspace or return to PhotoNotes. Administrative functions depend on your account role; review account and environment scope before modifying records.',terms:['Account access']},
 {match:'Submit Decision|Review Guidance|Status Descriptions',text:'Review the issue evidence and workflow definitions, choose the appropriate decision, and write clear instructions for the next action. Submit only after checking the report and intended status transition.',terms:['App issue','Retest','Status']},
 {match:'Send Details for Review',text:'Send the additional reproduction details entered for this app issue. Answer the requested question and describe actual observed behavior. Check the resulting review status.',terms:['App issue']},
 {match:'Retest Succeeded|Retest Failed|Unable to Retest',text:'Record the outcome of the requested repair retest. Repeat the exact steps on your device first, write what happened, and choose success, failure, or unable to test accurately. A deployment alone is not a successful retest.',terms:['Retest','App issue']},
 {match:'Enable issue notifications',text:'Request browser notification permission for issue updates. Check browser/device notification settings if blocked. Alerts are separate from the repair and retest record.',terms:['Notification']},
 {match:'Create assignment|Add step|Save draft|Publish reviewed assignment|Preview tester instructions|Close editor|Remove step',text:'Create or edit the testing instructions in the order the tester should follow. Each step should state the action and observable expected result. Preview and review the assignment before publishing; a draft is not yet the tester’s final instruction.',terms:['Testing assignment','Draft']},
 {match:'Submit.*assignment|Submit.*results|Save.*progress|Mark reviewed|Return for retesting|Refresh results|Refresh assignments',text:'Record or review testing results against the assignment steps. Save progress during testing, submit after recording outcomes and defects, and return specific failed steps for retesting when needed. Mark reviewed only after evaluating the submitted evidence.',terms:['Testing assignment','Retest']},
 {match:'Report.*problem|Report.*issue',text:'Report a PhotoNotes application problem with the exact steps, expected result, actual result, and screenshot. This is separate from capturing a road or maintenance issue.',terms:['App issue']},
 {match:'GPS Address',text:'Choose this source photo for a matched Before/After comparison. Review its location and viewpoint before capturing the After image.',terms:['Before/after']},
 {match:'Download assignment PDF',text:'Download this assignment’s instructions as a PDF. Follow the current published steps and record actual results in Testing Dashboard.',terms:['Testing assignment','PDF']},
 {match:'^#$',text:'Open the linked issue report or record to inspect its details and status before deciding the next action.',terms:['App issue']},
 {match:'^Save$|^Add$|^Create$',text:'Save or add the item entered in this form. Check the labeled fields and target record first. Read the resulting status, and do not assume that saving also sends or approves it.',terms:['Status']},
 {match:'Install|home screen|Official installation|Full installation',text:'Follow the installation instructions for your device and browser. The icon uses the same PhotoNotes account. Verify pending uploads before changing browsers or clearing storage; not every feature works offline.',terms:['Installation','Local save']},
 {match:'Approve Photos|Request Changes',text:'Review the photographs and message, enter your name and comments, then record your approval or requested changes. A response records the review decision; it does not certify facts outside the pictured evidence.',terms:['Approval','Evidence']},
 {match:'(?:Send|Submit) Completion Photos',text:'Upload clear photographs showing the completed work, include the requested name and note, and submit. The property manager will review the returned evidence before closing the maintenance item.',terms:['Completion link','Verification']}
];
// Physical-context QR guidance stays modular during concurrent integration.
add('qrAssetPhoto','Take or choose a current photograph for this asset using the existing condition-photo form. Review Photo Purpose, Current Condition and Photo Note, then Add Photo to Asset History. Selecting a file does not save it; the saved photograph remains associated with this asset automatically.',['QR code']);
add('data-qr-target|qrCreate','Create an optional QR code for this saved photographic record. Place its label at the physical subject. Scanning opens the existing record only after sign-in and a fresh authorization check. Asset Add Photo saves directly to existing asset history. This does not grant access or accept outside uploads.',['QR code']);
add('qrLabel|qrProperty','Edit the human-readable printed label and optional property name. These edits affect only the downloaded or printed label, not the saved record. Anyone can read a printed label, so use non-sensitive text.',['QR label']);
add('qrDownload|qrPrint','Download a PNG label or open a clean print window. The label includes Photo Notes, your chosen name, optional property and QR code. Print at a readable size and test scanning on the installed phone. A downloaded image is not proof of printing.',['QR label']);
add('qrReissue|qrDisable','Reissue replaces the token and invalidates every old printed label. Disable stops this QR link without deleting the record or its photographs. Create after disabling issues a new token. Replace physical labels after reissuing.',['QR code']);
add('qrClose','Close the QR code preview. Existing QR status and saved photographs remain unchanged.',['QR code']);
Object.assign(terms,{'QR code':'A scannable Photo Notes link that identifies a photographic context. Possession grants no access; sign-in and record authorization are required.','QR label':'A printed or downloaded QR code with a short human-readable name. Use non-sensitive text because anyone can read a physical label.'});
add('aiHeading|aiProvider|aiModel|aiRefreshModels|aiSave','Super Admin only: choose OpenAI, Anthropic or Grok, then choose a photo-analysis model and Save AI Selection. The saved choice applies to new AI requests across every edition. Refresh Models loads the models available to the server API account. Capability order is approximate; unranked models appear last and incompatible models cannot be selected. A company must have its server API key configured. Keys are never displayed here. Saving changes the model without changing photo access or enabling edition features.',['AI API model','AI company']);
add('aiRefreshUsage','Refresh the last 30 days of Photo Notes AI requests grouped by calendar day in America/Chicago. USD estimates use provider token counts and standard published rates stored when the request completes. Unknown pricing, failed requests without usage and pending ledger entries are counted as unknown costs and excluded from totals. Tracking starts with this feature, without historical backfill. These estimates do not include taxes, credits, negotiated rates or activity outside Photo Notes and are not provider invoices.',['Daily AI cost','AI tokens']);
Object.assign(terms,{'AI API model':'The server model selected by Super Admin for shared AI photo analysis in every Photo Notes edition.','AI company':'OpenAI, Anthropic or Grok, connected using server-held API credentials.','Daily AI cost':'Estimated USD charges from tracked Photo Notes API calls, grouped by day in America/Chicago. Unknown costs are excluded, rather than counted as zero.','AI tokens':'Provider-reported input and output units, including image input and reasoning output where reported, used to estimate API charges.'});
Object.assign(terms,{'Active time':'Estimated time with the app visible, ending after one minute without interaction. It is not total time signed in.','Session':'A browser-tab visit with an authenticated user, including return visits using an existing sign-in.','Screen visit':'Navigation to an app area, grouped by user and edition. Screen tracking begins with this release.'});
// Searchable workflow guidance lives with the authored control explanations.
const proEditions=['general','pro','contractor','paving','asphalt','hoa','property','concrete','roofer'];
Object.assign(terms,{'Security Issue Reporter Pro':'A PhotoNotes AI edition with the same Capture, photo notes, and Send/Share tools as Basic. The Pro name does not enable additional Pro features.'});
const allEditions=['basic','security','issue','roads',...proEditions];
const generalGuidance=[
 {title:'Saved Capture Settings and reusing photo context',editions:proEditions,text:'Use Saved Capture Settings to save reusable defaults for this account and edition. Use Saved Settings or Last Used Settings applies them deliberately; review the choices before taking and saving a new photograph. Save Current Settings excludes photos, narrative, location, time, jobs and properties. Duplicate for New Photo instead starts one new capture from safe context on an existing Photo Note. Copy Notes is optional and must be checked for facts belonging to the earlier photograph. Neither action copies photographic evidence or creates a relationship.',terms:['Saved Capture Settings','Context reuse','Local save']},
 {title:'Security Issue Reporter Pro',editions:['security'],text:'Security Issue Reporter Pro has the same tools and behavior as Basic. Capture a photo, add or record notes and an optional topic, then use Send/Share. It does not add security-specific reporting fields or additional Pro tools.',terms:['Security Issue Reporter Pro','Local save']},
 {title:'Custom Fields and Additional Details',editions:proEditions,text:'Manage Custom Fields creates Short Text, Number, Date, Yes / No or Choice metadata for your own photos, scoped to all your Pro editions or this edition. Expand Additional Details in Capture and complete any required fields before Save. Edit Additional Details changes saved values without replacing original photographic evidence. Deactivating a field preserves historical values. Search includes saved values; Choice and Yes / No fields also support filters. Documents include completed values.',terms:['Custom Field','Field scope','Field revision','Evidence']},
 {title:'Saved Views, Favorites and Flagged photos',editions:proEditions,text:'Save View stores search and supported filters for this edition and workspace. Results update as matching photos arrive; a view stores neither photo copies nor a fixed selection. Default applies a view when its workspace opens. All Photos or All Records clears it for the current visit without deleting the saved default. Favorite and Flagged are separate personal markers. They do not create reminders, change maintenance priority, or appear in customer outputs.',terms:['Saved View','Default View','Favorite','Flagged']},
 {title:'Related Photos and Internal Discussion',editions:proEditions,text:'Related Photos links independently saved photos in your library. Select existing photos, optionally describe the relationship, and save. Remove Relationship keeps both photos; relationship changes appear in both histories. Comments opens Internal Discussion for a saved photo. Post, Reply and Edit require a connection. Review @Name mentions for the intended authorized team member. Comments stay out of external documents and customer responses; preserve an unfinished draft before leaving.',terms:['Related Photos','Relationship type','Internal Discussion','Mention']},
 {title:'Location Intelligence and finding a photographed subject',editions:proEditions,text:'Location Intelligence keeps original Capture Location separate from an editable Subject Location. Open the map, set the subject pin or coordinates and landmark description, then Save. These corrections appear in photo history without changing original GPS. Find This Location uses current device GPS for approximate distance and bearing. Open in Maps requests directions from your mapping app. Satellite imagery can be outdated; maps and saving corrections require a connection.',terms:['Capture Location','Subject Location','Location Description','Camera Direction','GPS']},
 {title:'Request Photos from someone outside Photo Notes',editions:proEditions,text:'Open Request Photos, name 1 to 8 requested views and provide clear instructions. Create the private link, then copy or share it yourself. Creating the request sends no email or SMS. Recipients need no account. Anyone with the link can submit until it closes or expires. Links last 14 days by default, configurable from 1 to 30 days. Allow partial submissions permits return visits for missing views. Review received photos and history; completion requires every requested view. Cancel closes the link and retains received photographs.',terms:['Photo Request','Requested view','Private link','Request status','Upload']},
 {title:'QR labels for photographic records',editions:proEditions,text:'Create / Manage QR Code makes a label for a saved photographic record. Download or print it and test scanning at the physical subject. Printed names should contain no sensitive information. Scanning requires sign-in and current authorization; the code grants no additional access. Reissue invalidates old labels, so replace them. Disable closes the QR link while retaining the record and its photographs.',terms:['QR code','QR label','Account access']},
 {title:'Camera Readers and Scanners',editions:['contractor','paving','asphalt','concrete','hoa','property','roofer'],feature:'camera_readers',text:'Camera Tools shows only scanners supported by your industry edition and enabled account access. Ordinary Pro has no new scanner tools. Material labels and plans/sketches are available in all six industry editions. Business Cards is available in General Contractor Pro, Paving Pro, Concrete Pro, HOA Maintenance Pro, Property Manager Pro and Roofer Pro. Equipment plates and gauges exclude Roofer. Photograph or import a legible source, run Read and correct every value against the image. Save Record stores the reviewed reading with its source photo. Open in Photo Library creates or opens its linked Photo Note. Saved records offer PDF or Word reports; business cards also offer a Contact File. Download and sharing are separate actions. Review analog gauge readings against the printed scale.',terms:['Camera reader','AI','Evidence','Contact file','Share sheet']},
 {title:'Proposal Exhibit from a saved document',editions:proEditions,text:'Open an existing Create document and choose Proposal Exhibit. Set Letter orientation, reference, header, footer, visible details and maximum photos per page. Long notes may create additional pages. Optional text boxes use page positions measured in inches and can overlap content. Update Preview / Save Draft stores settings on this device for this account and document. Inspect every page before Print / Save as PDF, choose matching paper and orientation, and turn off browser headers and footers. This neither prices a proposal nor sends it.',terms:['Proposal exhibit','Document','Draft','PDF']},
 {title:'Property Areas, routes and photographic history',editions:['property'],text:'Create named Areas within a Property to organize photos, assets, maintenance records and inspection routes. An Area is optional and separate from Exact Location and GPS. Inactive Areas remain on historical records and filters. On an existing record Save Area is separate from Save Maintenance Record. Follow route stops during a guided visit, record requested views and review the asset or maintenance photo timeline. Review completion photos before verification and use reports and dashboard notifications to track recorded work.',terms:['Property Area','Inactive Area','Exact Location','Inspection route','Property visit','Verification']},
 {title:'Document Damage / Incident',editions:['property'],text:'Select a Property and start Document Damage / Incident. Save factual context, distinguishing Observed/Documented Time from optional Reported Incident Time. Capture the requested Overview, Damage, Close-Up, Surrounding Area and Identification views, or skip an irrelevant view with a reason. Additional Photos can repeat. Use Capture Save for each photo and wait for confirmed uploads. Review the incident and download PDF or Word with uploaded photos and skipped-view reasons. Save Incident Context is separate from photo saves. This workflow creates no maintenance item, insurance claim or verified cause.',terms:['Damage / Incident','Incident view','Observed time','Reported incident time','Upload']},
 {title:'Concrete photo analysis and review',editions:['concrete'],text:'Analyze Photo sends a saved photograph to the configured AI provider. Compare suggestions with the photograph and existing values, correct observations and findings, then check Apply only for fields you want to replace. Accept / Save Review records a reviewed observation for reports and search; unchecked fields retain existing values. Reject retains the run without applying it. History preserves earlier runs, model and timestamps. Rerun creates new suggestions. Exact location, mix and measurements remain unchanged. AI confidence is not engineering or safety certification.',terms:['Visual analysis','AI Suggested','User Reviewed','Analysis confidence']}
];
const workflowArticle=(title,keys,editions=proEditions)=>({title,editions,text:keys.map(key=>{const rule=rules.find(r=>r.keys.includes(key));if(!rule)throw Error('Missing workflow Help: '+key);return rule.text;}).join(' '),terms:[...new Set(keys.flatMap(key=>rules.find(r=>r.keys.includes(key)).terms))]});
generalGuidance.push(
 workflowArticle('Scheduled Photos and recurring follow-ups',['fuOpen','fuDate','data-fu-take','data-fu-skip','fuRead']),
 workflowArticle('Export Presets and document settings',['epLibrary','newDocument']),
 workflowArticle('Annotation templates and photo location markings',['annotationTemplateName','batchTemplate']),
 workflowArticle('Match and compare Before & After photographs',['data-view-pair']),
 workflowArticle('Recover an unfinished capture and finish Record Notes',['takephoto','dictate'],allEditions),
 workflowArticle('Result Screenshots and issue retesting',['issueSend'],allEditions)
);

add('readerJobFilter','Choose All Jobs to see saved scanner records across your jobs, one job to show only its records, or Unassigned for records without a job. Filtering does not move or change records. Older records linked to a Photo Note retain that photo’s job association until you explicitly save a Record job choice.',['Job','Evidence']);
add('readerJobAssignment','Choose the job for this scanner record, or Unassigned, then Save Record. This changes only the scanner record job assignment. A Photo Note first created through Open Photo inherits the selected job. Changing this choice does not move an existing linked Photo Note or change source photos, notes or reviewed fields.',['Job','Evidence']);

window.PhotoNotesHelpCatalog={rules,terms,textRules,generalGuidance};
})();
